create temp table _portfolio_migration_cases on commit drop as
select
  (item->>'id')::uuid as id,
  item->>'legacy_id' as legacy_id,
  item->>'legacy_slug' as legacy_slug,
  item->>'slug' as slug,
  item->>'title' as title,
