  coalesce(item->>'excerpt', '') as excerpt,
  coalesce(item->'content_json', '{"type":"doc","content":[]}'::jsonb) as content_json,
  coalesce(item->>'content_html', '') as content_html,
  coalesce(item->>'cover_url', '') as cover_url,
  nullif(item->>'cover_storage_bucket', '') as cover_storage_bucket,
  nullif(item->>'cover_storage_path', '') as cover_storage_path,
  coalesce(item->>'external_url', '') as external_url,
  coalesce((item->>'featured_on_home')::boolean, false) as featured_on_home,
  coalesce((item->>'home_order')::integer, 999) as home_order,
  coalesce((item->>'portfolio_order')::integer, 999) as portfolio_order,
  coalesce(item->>'seo_title', '') as seo_title,
  coalesce(item->>'seo_description', '') as seo_description,
  nullif(item->>'published_at', '')::timestamptz as published_at,
  nullif(item->>'created_by', '')::uuid as created_by,
  nullif(item->>'updated_by', '')::uuid as updated_by,
  coalesce((item->>'version')::integer, 1) as version,
  nullif(item->>'created_at', '')::timestamptz as created_at,
  nullif(item->>'updated_at', '')::timestamptz as updated_at
from jsonb_array_elements($portfolio_migration_json$[{"id":"aad05df7-b810-5b7b-bdb2-c17c3d62e2eb","legacy_id":"a-primeira-segunda-feira","legacy_slug":"a-primeira-segunda-feira","slug":"a-primeira-segunda-feira","title":"A Primeira Segunda-Feira","status":"published","categories":["UI/UX Design"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sobre o Projeto"}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto consistiu no design de uma landing page de alta conversão para \"A PRIMEIRA SEGUNDA-FEIRA: O CURSO\". Trata-se de um programa online de alto valor, baseado em um livro best-seller, focado em apoiar executivos e empreendedores na transição de suas carreiras corporativas para um novo ciclo profissional planejado e com propósito."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O público-alvo deste curso é composto por profissionais experientes e de alto escalão. O desafio de design era criar uma página que falasse diretamente a esse público, transmitindo autoridade, empatia e um profundo entendimento de suas dores. A página precisava ser mais do que informativa; deveria ser uma jornada de persuasão que validasse suas ansiedades e apresentasse uma solução estruturada e crível, evitando \"fórmulas prontas\"."}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução de Design: Uma Arquitetura de Conversão Estratégica"}]},{"type":"paragraph","content":[{"type":"text","text":"A landing page foi estruturada como uma narrativa estratégica, onde cada seção foi projetada para construir valor, gerar confiança e guiar o executivo passo a passo até a conversão."}]},{"type":"paragraph","content":[{"type":"text","text":"1. Conexão Imediata (Hero Section) A página abre com uma pergunta poderosa e empática: \"Você já imaginou como será a sua primeira segunda-feira fora do mundo corporativo?\". Esta abordagem captura imediatamente a atenção do público-alvo, validando sua principal preocupação e contrastando o \"salto no escuro\" com a promessa de um ciclo \"leve, planejado e cheio de significado\"."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Qualificação de Público (Filtro de Relevância) Para aumentar a relevância e a taxa de conversão, a página utiliza seções claras de \"Para quem é\" e \"Para quem não é\". Esta é uma escolha de design deliberada para filtrar o tráfego, fazendo com que os profissionais certos se sintam compreendidos e evitando leads desqualificados."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Apresentação de Valor (O Método) A seção \"O que você vai aprender\" estabelece a seriedade do programa. Em vez de promessas vagas, ela apresenta um currículo robusto baseado em um método proprietário, o \"método ANCOR\". Isso constrói um valor intelectual significativo."}]},{"type":"paragraph","content":[{"type":"text","text":"4. Foco na Transformação (Benefícios) A seção \"O que você vai conquistar\" muda o foco dos recursos (aulas) para os resultados (a transformação). O design desta seção usa checkmarks para listar benefícios emocionais e práticos de alto impacto, como \"Redução da ansiedade diante do novo ciclo\" e \"Segurança emocional para desapegar do status...\"."}]},{"type":"paragraph","content":[{"type":"text","text":"5. Prova Social de Alto Nível (Credibilidade) A credibilidade é estabelecida de duas formas:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Depoimentos: A prova social é altamente segmentada. Não são apenas citações; são de executivos reais, com menção à indústria e idade, o que gera uma identificação imediata com o público-alvo."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Autoridade das Instrutoras: A seção \"Sobre as instrutoras\" é fundamental. Ela posiciona Flavia Perez e Maristela Gorayb como especialistas absolutas, citando seus 25 e 30 anos de experiência executiva em grandes multinacionais, além de serem autoras best-sellers."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"6. Funil de Vendas Claro (A Oferta) A página apresenta os pacotes e preços de forma clara, usando a tática de ancoragem com um plano \"Mais Popular\" (o Plano Completo) para guiar a decisão. Antes da chamada final, uma seção de FAQ é usada para quebrar as últimas objeções, como \"Ainda estou no mundo corporativo. Vai servir para mim?\"."}]},{"type":"paragraph","content":[{"type":"text","text":"UI/UX Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Sobre o Projeto"}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto consistiu no design de uma landing page de alta conversão para \"A PRIMEIRA SEGUNDA-FEIRA: O CURSO\". Trata-se de um programa online de alto valor, baseado em um livro best-seller, focado em apoiar executivos e empreendedores na transição de suas carreiras corporativas para um novo ciclo profissional planejado e com propósito."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O público-alvo deste curso é composto por profissionais experientes e de alto escalão. O desafio de design era criar uma página que falasse diretamente a esse público, transmitindo autoridade, empatia e um profundo entendimento de suas dores. A página precisava ser mais do que informativa; deveria ser uma jornada de persuasão que validasse suas ansiedades e apresentasse uma solução estruturada e crível, evitando \"fórmulas prontas\"."}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução de Design: Uma Arquitetura de Conversão Estratégica"}]},{"type":"paragraph","content":[{"type":"text","text":"A landing page foi estruturada como uma narrativa estratégica, onde cada seção foi projetada para construir valor, gerar confiança e guiar o executivo passo a passo até a conversão."}]},{"type":"paragraph","content":[{"type":"text","text":"1. Conexão Imediata (Hero Section) A página abre com uma pergunta poderosa e empática: \"Você já imaginou como será a sua primeira segunda-feira fora do mundo corporativo?\". Esta abordagem captura imediatamente a atenção do público-alvo, validando sua principal preocupação e contrastando o \"salto no escuro\" com a promessa de um ciclo \"leve, planejado e cheio de significado\"."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Qualificação de Público (Filtro de Relevância) Para aumentar a relevância e a taxa de conversão, a página utiliza seções claras de \"Para quem é\" e \"Para quem não é\". Esta é uma escolha de design deliberada para filtrar o tráfego, fazendo com que os profissionais certos se sintam compreendidos e evitando leads desqualificados."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Apresentação de Valor (O Método) A seção \"O que você vai aprender\" estabelece a seriedade do programa. Em vez de promessas vagas, ela apresenta um currículo robusto baseado em um método proprietário, o \"método ANCOR\". Isso constrói um valor intelectual significativo."}]},{"type":"paragraph","content":[{"type":"text","text":"4. Foco na Transformação (Benefícios) A seção \"O que você vai conquistar\" muda o foco dos recursos (aulas) para os resultados (a transformação). O design desta seção usa checkmarks para listar benefícios emocionais e práticos de alto impacto, como \"Redução da ansiedade diante do novo ciclo\" e \"Segurança emocional para desapegar do status...\"."}]},{"type":"paragraph","content":[{"type":"text","text":"5. Prova Social de Alto Nível (Credibilidade) A credibilidade é estabelecida de duas formas:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Depoimentos: A prova social é altamente segmentada. Não são apenas citações; são de executivos reais, com menção à indústria e idade, o que gera uma identificação imediata com o público-alvo."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Autoridade das Instrutoras: A seção \"Sobre as instrutoras\" é fundamental. Ela posiciona Flavia Perez e Maristela Gorayb como especialistas absolutas, citando seus 25 e 30 anos de experiência executiva em grandes multinacionais, além de serem autoras best-sellers."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"6. Funil de Vendas Claro (A Oferta) A página apresenta os pacotes e preços de forma clara, usando a tática de ancoragem com um plano \"Mais Popular\" (o Plano Completo) para guiar a decisão. Antes da chamada final, uma seção de FAQ é usada para quebrar as últimas objeções, como \"Ainda estou no mundo corporativo. Vai servir para mim?\"."}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p><strong>Sobre o Projeto</strong></p><p>O projeto consistiu no design de uma landing page de alta conversão para \"A PRIMEIRA SEGUNDA-FEIRA: O CURSO\". Trata-se de um programa online de alto valor, baseado em um livro best-seller, focado em apoiar executivos e empreendedores na transição de suas carreiras corporativas para um novo ciclo profissional planejado e com propósito.</p><p><strong>O Desafio</strong></p><p>O público-alvo deste curso é composto por profissionais experientes e de alto escalão. O desafio de design era criar uma página que falasse diretamente a esse público, transmitindo autoridade, empatia e um profundo entendimento de suas dores. A página precisava ser mais do que informativa; deveria ser uma jornada de persuasão que validasse suas ansiedades e apresentasse uma solução estruturada e crível, evitando \"fórmulas prontas\".</p><p><strong>A Solução de Design: Uma Arquitetura de Conversão Estratégica</strong></p><p>A landing page foi estruturada como uma narrativa estratégica, onde cada seção foi projetada para construir valor, gerar confiança e guiar o executivo passo a passo até a conversão.</p><p><strong>1. Conexão Imediata (Hero Section)</strong><br>A página abre com uma pergunta poderosa e empática: \"Você já imaginou como será a sua primeira segunda-feira fora do mundo corporativo?\". Esta abordagem captura imediatamente a atenção do público-alvo, validando sua principal preocupação e contrastando o \"salto no escuro\" com a promessa de um ciclo \"leve, planejado e cheio de significado\".</p><p><strong>2. Qualificação de Público (Filtro de Relevância)</strong><br>Para aumentar a relevância e a taxa de conversão, a página utiliza seções claras de \"Para quem é\" e \"Para quem não é\". Esta é uma escolha de design deliberada para filtrar o tráfego, fazendo com que os profissionais certos se sintam compreendidos e evitando leads desqualificados.</p><p><strong>3. Apresentação de Valor (O Método)</strong><br>A seção \"O que você vai aprender\" estabelece a seriedade do programa. Em vez de promessas vagas, ela apresenta um currículo robusto baseado em um método proprietário, o \"método ANCOR\". Isso constrói um valor intelectual significativo.</p><p><strong>4. Foco na Transformação (Benefícios)</strong><br>A seção \"O que você vai conquistar\" muda o foco dos<em>recursos</em>(aulas) para os<em>resultados</em>(a transformação). O design desta seção usa<em>checkmarks</em>para listar benefícios emocionais e práticos de alto impacto, como \"Redução da ansiedade diante do novo ciclo\" e \"Segurança emocional para desapegar do status...\".</p><p><strong>5. Prova Social de Alto Nível (Credibilidade)</strong><br>A credibilidade é estabelecida de duas formas:</p><ul><li><p><strong>Depoimentos:</strong>A prova social é altamente segmentada. Não são apenas citações; são de executivos reais, com menção à indústria e idade, o que gera uma identificação imediata com o público-alvo.</p></li><li><p><strong>Autoridade das Instrutoras:</strong>A seção \"Sobre as instrutoras\" é fundamental. Ela posiciona Flavia Perez e Maristela Gorayb como especialistas absolutas, citando seus 25 e 30 anos de experiência executiva em grandes multinacionais, além de serem autoras best-sellers.</p></li></ul><p><strong>6. Funil de Vendas Claro (A Oferta)</strong><br>A página apresenta os pacotes e preços de forma clara, usando a tática de ancoragem com um plano \"Mais Popular\" (o Plano Completo) para guiar a decisão. Antes da chamada final, uma seção de FAQ é usada para quebrar as últimas objeções, como \"Ainda estou no mundo corporativo. Vai servir para mim?\".</p>A Primeira Segunda-Feira A Primeira Segunda-Feira<p>UI/UX Design</p><p><strong>Sobre o Projeto</strong></p><p>O projeto consistiu no design de uma landing page de alta conversão para \"A PRIMEIRA SEGUNDA-FEIRA: O CURSO\". Trata-se de um programa online de alto valor, baseado em um livro best-seller, focado em apoiar executivos e empreendedores na transição de suas carreiras corporativas para um novo ciclo profissional planejado e com propósito.</p><p><strong>O Desafio</strong></p><p>O público-alvo deste curso é composto por profissionais experientes e de alto escalão. O desafio de design era criar uma página que falasse diretamente a esse público, transmitindo autoridade, empatia e um profundo entendimento de suas dores. A página precisava ser mais do que informativa; deveria ser uma jornada de persuasão que validasse suas ansiedades e apresentasse uma solução estruturada e crível, evitando \"fórmulas prontas\".</p><p><strong>A Solução de Design: Uma Arquitetura de Conversão Estratégica</strong></p><p>A landing page foi estruturada como uma narrativa estratégica, onde cada seção foi projetada para construir valor, gerar confiança e guiar o executivo passo a passo até a conversão.</p><p><strong>1. Conexão Imediata (Hero Section)</strong><br>A página abre com uma pergunta poderosa e empática: \"Você já imaginou como será a sua primeira segunda-feira fora do mundo corporativo?\". Esta abordagem captura imediatamente a atenção do público-alvo, validando sua principal preocupação e contrastando o \"salto no escuro\" com a promessa de um ciclo \"leve, planejado e cheio de significado\".</p><p><strong>2. Qualificação de Público (Filtro de Relevância)</strong><br>Para aumentar a relevância e a taxa de conversão, a página utiliza seções claras de \"Para quem é\" e \"Para quem não é\". Esta é uma escolha de design deliberada para filtrar o tráfego, fazendo com que os profissionais certos se sintam compreendidos e evitando leads desqualificados.</p><p><strong>3. Apresentação de Valor (O Método)</strong><br>A seção \"O que você vai aprender\" estabelece a seriedade do programa. Em vez de promessas vagas, ela apresenta um currículo robusto baseado em um método proprietário, o \"método ANCOR\". Isso constrói um valor intelectual significativo.</p><p><strong>4. Foco na Transformação (Benefícios)</strong><br>A seção \"O que você vai conquistar\" muda o foco dos<em>recursos</em>(aulas) para os<em>resultados</em>(a transformação). O design desta seção usa<em>checkmarks</em>para listar benefícios emocionais e práticos de alto impacto, como \"Redução da ansiedade diante do novo ciclo\" e \"Segurança emocional para desapegar do status...\".</p><p><strong>5. Prova Social de Alto Nível (Credibilidade)</strong><br>A credibilidade é estabelecida de duas formas:</p><ul><li><p><strong>Depoimentos:</strong>A prova social é altamente segmentada. Não são apenas citações; são de executivos reais, com menção à indústria e idade, o que gera uma identificação imediata com o público-alvo.</p></li><li><p><strong>Autoridade das Instrutoras:</strong>A seção \"Sobre as instrutoras\" é fundamental. Ela posiciona Flavia Perez e Maristela Gorayb como especialistas absolutas, citando seus 25 e 30 anos de experiência executiva em grandes multinacionais, além de serem autoras best-sellers.</p></li></ul><p><strong>6. Funil de Vendas Claro (A Oferta)</strong><br>A página apresenta os pacotes e preços de forma clara, usando a tática de ancoragem com um plano \"Mais Popular\" (o Plano Completo) para guiar a decisão. Antes da chamada final, uma seção de FAQ é usada para quebrar as últimas objeções, como \"Ainda estou no mundo corporativo. Vai servir para mim?\".</p>Calendário Impresul 2024<p>Anterior</p><p>Anterior</p>Definna<p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/a-primeira-segunda-feira/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/a-primeira-segunda-feira/cover.jpg","external_url":"","featured_on_home":false,"home_order":999,"portfolio_order":25,"seo_title":"","seo_description":"","published_at":"2026-05-28T21:07:55.491007+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-05-28T21:07:55.491007+00:00"},{"id":"e7b81473-6aab-5767-a5a0-50649f556e77","legacy_id":"anima","legacy_slug":"anima","slug":"anima","title":"Anima+","status":"published","categories":["UI/UX Design","Branding"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O Anima+ é um aplicativo-plataforma focado no aprendizado de animação. Para pessoas que buscam mais conhecimento na área, o Anima+ é uma plataforma que ensina, de maneira interativa, a história, os conceitos, as produções digitais e analógicas dos diferentes tipos de animação e suas particularidades."}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto foi concebido como uma solução gratuita, contribuindo para a democratização do ensino e atraindo o interesse de mais profissionais para a área."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O desafio era criar uma plataforma de aprendizado que preenchesse uma lacuna no mercado: a falta de soluções acessíveis que abordassem os fundamentos da animação. Uma análise de plataformas similares identificou que muitas soluções são pagas, focadas mais em vender cursos do que em ensinar, e visualmente desorganizadas."}]},{"type":"paragraph","content":[{"type":"text","text":"A solução precisava ser gratuita e atender a dois públicos principais:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Público Primário : Estudantes de cursos da área criativa que buscam um conhecimento complementar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Público Secundário : Entusiastas que desejam saber se querem seguir profissionalmente na área ou simplesmente expandir seu conhecimento."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução de Design: Aprendizado Interativo e Gamificado"}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto foi estruturado em um processo de design completo, incluindo definição do problema, pesquisa de similares, arquitetura da informação, identidade visual, wireframes e prototipagem."}]},{"type":"paragraph","content":[{"type":"text","text":"1. Pesquisa e Estratégia: A fase de descoberta incluiu uma análise de plataformas de e-learning (como Domestika e Lumina) e aplicativos gamificados (como Duolingo e Perguntados) . A pesquisa identificou oportunidades claras: criar uma plataforma focada no ensino, visualmente organizada e com um ambiente \"jogável\" que não pressionasse o usuário. A estratégia foi validada com pesquisas quantitativas (17 respostas) e entrevistas qualitativas com o público-alvo e profissionais da área."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Arquitetura e Gamificação: O conceito central do Anima+ é a gamificação do aprendizado. O próprio logotipo reflete isso, combinando um rosto feliz (a emoção da \"animação\") com um joystick (a \"gamificação\"). A arquitetura da informação foi projetada para ser intuitiva, dividindo a experiência do usuário em quatro abas principais: Módulos, Progresso, Games e Perfil."}]},{"type":"paragraph","content":[{"type":"text","text":"3. A Experiência de Aprendizado: O design do aplicativo se materializa em um ecossistema de aprendizado completo e interativo:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Módulos de Aprendizado: O usuário avança por um caminho de aprendizado estruturado, com módulos sobre História, Tipos de Animação, Fundamentos, Empresas, etc.. Cada módulo é composto por aulas, vídeos e avaliações."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Games (Gamificação): Para tornar o aprendizado mais dinâmico , uma aba \"Games\" permite ao usuário exercitar seus conhecimentos. São quizzes no estilo trivia, separados por módulo , onde o usuário responde perguntas de múltipla escolha."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dashboard de Progresso: Uma seção dedicada permite ao usuário monitorar seu progresso, com gráficos de horas assistidas e um ranking de suas melhores pontuações nos games."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Perfil: Uma área para o usuário fazer anotações, adicionar amigos e gerenciar suas configurações."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"4. Identidade Visual: A marca \"Anima+\" utiliza uma tipografia amigável e arredondada (Renogare Soft) e uma paleta de cores vibrantes (azul, rosa, amarelo e verde) , criando uma atmosfera convidativa, divertida e lúdica para o aprendizado."}]},{"type":"paragraph","content":[{"type":"text","text":"UI/UX Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Branding"}]},{"type":"paragraph","content":[{"type":"text","text":"O Anima+ é um aplicativo-plataforma focado no aprendizado de animação. Para pessoas que buscam mais conhecimento na área, o Anima+ é uma plataforma que ensina, de maneira interativa, a história, os conceitos, as produções digitais e analógicas dos diferentes tipos de animação e suas particularidades."}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto foi concebido como uma solução gratuita, contribuindo para a democratização do ensino e atraindo o interesse de mais profissionais para a área."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O desafio era criar uma plataforma de aprendizado que preenchesse uma lacuna no mercado: a falta de soluções acessíveis que abordassem os fundamentos da animação. Uma análise de plataformas similares identificou que muitas soluções são pagas, focadas mais em vender cursos do que em ensinar, e visualmente desorganizadas."}]},{"type":"paragraph","content":[{"type":"text","text":"A solução precisava ser gratuita e atender a dois públicos principais:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Público Primário : Estudantes de cursos da área criativa que buscam um conhecimento complementar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Público Secundário : Entusiastas que desejam saber se querem seguir profissionalmente na área ou simplesmente expandir seu conhecimento."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução de Design: Aprendizado Interativo e Gamificado"}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto foi estruturado em um processo de design completo, incluindo definição do problema, pesquisa de similares, arquitetura da informação, identidade visual, wireframes e prototipagem."}]},{"type":"paragraph","content":[{"type":"text","text":"1. Pesquisa e Estratégia: A fase de descoberta incluiu uma análise de plataformas de e-learning (como Domestika e Lumina) e aplicativos gamificados (como Duolingo e Perguntados) . A pesquisa identificou oportunidades claras: criar uma plataforma focada no ensino, visualmente organizada e com um ambiente \"jogável\" que não pressionasse o usuário. A estratégia foi validada com pesquisas quantitativas (17 respostas) e entrevistas qualitativas com o público-alvo e profissionais da área."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Arquitetura e Gamificação: O conceito central do Anima+ é a gamificação do aprendizado. O próprio logotipo reflete isso, combinando um rosto feliz (a emoção da \"animação\") com um joystick (a \"gamificação\"). A arquitetura da informação foi projetada para ser intuitiva, dividindo a experiência do usuário em quatro abas principais: Módulos, Progresso, Games e Perfil."}]},{"type":"paragraph","content":[{"type":"text","text":"3. A Experiência de Aprendizado: O design do aplicativo se materializa em um ecossistema de aprendizado completo e interativo:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Módulos de Aprendizado: O usuário avança por um caminho de aprendizado estruturado, com módulos sobre História, Tipos de Animação, Fundamentos, Empresas, etc.. Cada módulo é composto por aulas, vídeos e avaliações."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Games (Gamificação): Para tornar o aprendizado mais dinâmico , uma aba \"Games\" permite ao usuário exercitar seus conhecimentos. São quizzes no estilo trivia, separados por módulo , onde o usuário responde perguntas de múltipla escolha."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dashboard de Progresso: Uma seção dedicada permite ao usuário monitorar seu progresso, com gráficos de horas assistidas e um ranking de suas melhores pontuações nos games."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Perfil: Uma área para o usuário fazer anotações, adicionar amigos e gerenciar suas configurações."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"4. Identidade Visual: A marca \"Anima+\" utiliza uma tipografia amigável e arredondada (Renogare Soft) e uma paleta de cores vibrantes (azul, rosa, amarelo e verde) , criando uma atmosfera convidativa, divertida e lúdica para o aprendizado."}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p>O Anima+ é um aplicativo-plataforma focado no aprendizado de animação. Para pessoas que buscam mais conhecimento na área, o Anima+ é uma plataforma que ensina, de maneira interativa, a história, os conceitos, as produções digitais e analógicas dos diferentes tipos de animação e suas particularidades.</p><p>O projeto foi concebido como uma solução gratuita, contribuindo para a democratização do ensino e atraindo o interesse de mais profissionais para a área.</p><p><strong>O Desafio</strong></p><p>O desafio era criar uma plataforma de aprendizado que preenchesse uma lacuna no mercado: a falta de soluções acessíveis que abordassem os fundamentos da animação. Uma análise de plataformas similares identificou que muitas soluções são pagas, focadas mais em vender cursos do que em ensinar, e visualmente desorganizadas.</p><p>A solução precisava ser gratuita e atender a dois públicos principais:</p><ul><li><p><strong>Público Primário</strong>: Estudantes de cursos da área criativa que buscam um conhecimento complementar.</p></li><li><p><strong>Público Secundário</strong>: Entusiastas que desejam saber se querem seguir profissionalmente na área ou simplesmente expandir seu conhecimento.</p></li></ul><p><strong>A Solução de Design: Aprendizado Interativo e Gamificado</strong></p><p>O projeto foi estruturado em um processo de design completo, incluindo definição do problema, pesquisa de similares, arquitetura da informação, identidade visual, wireframes e prototipagem.</p><p><strong>1. Pesquisa e Estratégia:</strong>A fase de descoberta incluiu uma análise de plataformas de e-learning (como Domestika e Lumina) e aplicativos gamificados (como Duolingo e Perguntados) . A pesquisa identificou oportunidades claras: criar uma plataforma focada no ensino, visualmente organizada e com um ambiente \"jogável\" que não pressionasse o usuário. A estratégia foi validada com pesquisas quantitativas (17 respostas) e entrevistas qualitativas com o público-alvo e profissionais da área.</p><p><strong>2. Arquitetura e Gamificação:</strong>O conceito central do Anima+ é a gamificação do aprendizado. O próprio logotipo reflete isso, combinando um rosto feliz (a emoção da \"animação\") com um joystick (a \"gamificação\"). A arquitetura da informação foi projetada para ser intuitiva, dividindo a experiência do usuário em quatro abas principais: Módulos, Progresso, Games e Perfil.</p><p><strong>3. A Experiência de Aprendizado:</strong>O design do aplicativo se materializa em um ecossistema de aprendizado completo e interativo:</p><ul><li><p><strong>Módulos de Aprendizado:</strong>O usuário avança por um caminho de aprendizado estruturado, com módulos sobre História, Tipos de Animação, Fundamentos, Empresas, etc.. Cada módulo é composto por aulas, vídeos e avaliações.</p></li><li><p><strong>Games (Gamificação):</strong>Para tornar o aprendizado mais dinâmico , uma aba \"Games\" permite ao usuário exercitar seus conhecimentos. São quizzes no estilo trivia, separados por módulo , onde o usuário responde perguntas de múltipla escolha.</p></li><li><p><strong>Dashboard de Progresso:</strong>Uma seção dedicada permite ao usuário monitorar seu progresso, com gráficos de horas assistidas e um ranking de suas melhores pontuações nos games.</p></li><li><p><strong>Perfil:</strong>Uma área para o usuário fazer anotações, adicionar amigos e gerenciar suas configurações.</p></li></ul><p><strong>4. Identidade Visual:</strong>A marca \"Anima+\" utiliza uma tipografia amigável e arredondada (Renogare Soft) e uma paleta de cores vibrantes (azul, rosa, amarelo e verde) , criando uma atmosfera convidativa, divertida e lúdica para o aprendizado.</p>Anima+ Anima+<p>UI/UX Design</p><p>Branding</p><p>O Anima+ é um aplicativo-plataforma focado no aprendizado de animação. Para pessoas que buscam mais conhecimento na área, o Anima+ é uma plataforma que ensina, de maneira interativa, a história, os conceitos, as produções digitais e analógicas dos diferentes tipos de animação e suas particularidades.</p><p>O projeto foi concebido como uma solução gratuita, contribuindo para a democratização do ensino e atraindo o interesse de mais profissionais para a área.</p><p><strong>O Desafio</strong></p><p>O desafio era criar uma plataforma de aprendizado que preenchesse uma lacuna no mercado: a falta de soluções acessíveis que abordassem os fundamentos da animação. Uma análise de plataformas similares identificou que muitas soluções são pagas, focadas mais em vender cursos do que em ensinar, e visualmente desorganizadas.</p><p>A solução precisava ser gratuita e atender a dois públicos principais:</p><ul><li><p><strong>Público Primário</strong>: Estudantes de cursos da área criativa que buscam um conhecimento complementar.</p></li><li><p><strong>Público Secundário</strong>: Entusiastas que desejam saber se querem seguir profissionalmente na área ou simplesmente expandir seu conhecimento.</p></li></ul><p><strong>A Solução de Design: Aprendizado Interativo e Gamificado</strong></p><p>O projeto foi estruturado em um processo de design completo, incluindo definição do problema, pesquisa de similares, arquitetura da informação, identidade visual, wireframes e prototipagem.</p><p><strong>1. Pesquisa e Estratégia:</strong>A fase de descoberta incluiu uma análise de plataformas de e-learning (como Domestika e Lumina) e aplicativos gamificados (como Duolingo e Perguntados) . A pesquisa identificou oportunidades claras: criar uma plataforma focada no ensino, visualmente organizada e com um ambiente \"jogável\" que não pressionasse o usuário. A estratégia foi validada com pesquisas quantitativas (17 respostas) e entrevistas qualitativas com o público-alvo e profissionais da área.</p><p><strong>2. Arquitetura e Gamificação:</strong>O conceito central do Anima+ é a gamificação do aprendizado. O próprio logotipo reflete isso, combinando um rosto feliz (a emoção da \"animação\") com um joystick (a \"gamificação\"). A arquitetura da informação foi projetada para ser intuitiva, dividindo a experiência do usuário em quatro abas principais: Módulos, Progresso, Games e Perfil.</p><p><strong>3. A Experiência de Aprendizado:</strong>O design do aplicativo se materializa em um ecossistema de aprendizado completo e interativo:</p><ul><li><p><strong>Módulos de Aprendizado:</strong>O usuário avança por um caminho de aprendizado estruturado, com módulos sobre História, Tipos de Animação, Fundamentos, Empresas, etc.. Cada módulo é composto por aulas, vídeos e avaliações.</p></li><li><p><strong>Games (Gamificação):</strong>Para tornar o aprendizado mais dinâmico , uma aba \"Games\" permite ao usuário exercitar seus conhecimentos. São quizzes no estilo trivia, separados por módulo , onde o usuário responde perguntas de múltipla escolha.</p></li><li><p><strong>Dashboard de Progresso:</strong>Uma seção dedicada permite ao usuário monitorar seu progresso, com gráficos de horas assistidas e um ranking de suas melhores pontuações nos games.</p></li><li><p><strong>Perfil:</strong>Uma área para o usuário fazer anotações, adicionar amigos e gerenciar suas configurações.</p></li></ul><p><strong>4. Identidade Visual:</strong>A marca \"Anima+\" utiliza uma tipografia amigável e arredondada (Renogare Soft) e uma paleta de cores vibrantes (azul, rosa, amarelo e verde) , criando uma atmosfera convidativa, divertida e lúdica para o aprendizado.</p>LumiLab<p>Anterior</p><p>Anterior</p>Morangos Mofados<p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/anima/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/anima/cover.jpg","external_url":"","featured_on_home":false,"home_order":999,"portfolio_order":9,"seo_title":"","seo_description":"","published_at":"2026-05-28T20:21:07.399076+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-05-28T20:21:07.399076+00:00"},{"id":"63a0e510-2cdb-5fb6-ad47-261176540ed5","legacy_id":"atitus-educação","legacy_slug":"atitus-educação","slug":"atitus-educação","title":"Atitus Educação","status":"published","categories":["UI/UX Design","Desenvolvimento","Branding","Editorial"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Atitus Educação faz parte de um Ecossistema de Educação e Inovação focado em preparar e impulsionar pessoas para o futuro. Com um olhar atento ao mercado, a instituição desenvolveu um modelo educacional inovador, flexível e focado em resultados, formando profissionais capazes de transformar a realidade em que vivem."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O desafio era utilizar o design como uma ferramenta estratégica para impulsionar o crescimento da instituição em múltiplas frentes: otimizar a captação de novos alunos, aumentar a retenção dos alunos existentes, fortalecer a presença da marca e engajar a comunidade online."}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução de Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Foi implementada uma estratégia de design multifacetada, atuando em pontos críticos da jornada do estudante e da comunicação da marca."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Otimização da Conversão (Aquisição): A interface da página de inscrições do vestibular foi completamente projetada com foco na otimização do funil de conversão. O resultado direto dessa otimização foi a contribuição para a captação de mais de 800 novos alunos ."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Landing Pages Estratégicas: Foram desenvolvidas Landing Pages dedicadas aos projetos mais estratégicos da instituição, como o lançamento da Escola de Agronegócio e a apresentação do Ecossistema de Negócios Atitus. Essas páginas serviram como ferramentas focadas para comunicar novas iniciativas e capturar o interesse de públicos específicos."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Comunicação Visual e Marketing de Conteúdo: Foram criados e executados os key visuals e a comunicação visual para diversas frentes de marketing. O impacto foi mensurável: Retenção: As campanhas de retenção resultaram na rematrícula de centenas de alunos."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Engajamento: O trabalho de design dedicado ao podcast Atitus Talks suportou um crescimento expressivo de 259% em ouvintes ."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gestão de Identidade Visual: Foi realizado um gerenciamento ativo da consistência da identidade visual da marca através da criação de múltiplos conteúdos para diversos canais. Essa consistência contribuiu para um aumento significativo na presença online da marca, com um crescimento de mais de 20.000 seguidores nas redes sociais."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"UI/UX Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Desenvolvimento"}]},{"type":"paragraph","content":[{"type":"text","text":"Branding"}]},{"type":"paragraph","content":[{"type":"text","text":"Editorial"}]},{"type":"paragraph","content":[{"type":"text","text":"A Atitus Educação faz parte de um Ecossistema de Educação e Inovação focado em preparar e impulsionar pessoas para o futuro. Com um olhar atento ao mercado, a instituição desenvolveu um modelo educacional inovador, flexível e focado em resultados, formando profissionais capazes de transformar a realidade em que vivem."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O desafio era utilizar o design como uma ferramenta estratégica para impulsionar o crescimento da instituição em múltiplas frentes: otimizar a captação de novos alunos, aumentar a retenção dos alunos existentes, fortalecer a presença da marca e engajar a comunidade online."}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução de Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Foi implementada uma estratégia de design multifacetada, atuando em pontos críticos da jornada do estudante e da comunicação da marca."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Otimização da Conversão (Aquisição): A interface da página de inscrições do vestibular foi completamente projetada com foco na otimização do funil de conversão. O resultado direto dessa otimização foi a contribuição para a captação de mais de 800 novos alunos ."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Landing Pages Estratégicas: Foram desenvolvidas Landing Pages dedicadas aos projetos mais estratégicos da instituição, como o lançamento da Escola de Agronegócio e a apresentação do Ecossistema de Negócios Atitus. Essas páginas serviram como ferramentas focadas para comunicar novas iniciativas e capturar o interesse de públicos específicos."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Comunicação Visual e Marketing de Conteúdo: Foram criados e executados os key visuals e a comunicação visual para diversas frentes de marketing. O impacto foi mensurável: Retenção: As campanhas de retenção resultaram na rematrícula de centenas de alunos."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Engajamento: O trabalho de design dedicado ao podcast Atitus Talks suportou um crescimento expressivo de 259% em ouvintes ."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gestão de Identidade Visual: Foi realizado um gerenciamento ativo da consistência da identidade visual da marca através da criação de múltiplos conteúdos para diversos canais. Essa consistência contribuiu para um aumento significativo na presença online da marca, com um crescimento de mais de 20.000 seguidores nas redes sociais."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p>A Atitus Educação faz parte de um Ecossistema de Educação e Inovação focado em preparar e impulsionar pessoas para o futuro. Com um olhar atento ao mercado, a instituição desenvolveu um modelo educacional inovador, flexível e focado em resultados, formando profissionais capazes de transformar a realidade em que vivem.</p><p><strong>O Desafio</strong></p><p>O desafio era utilizar o design como uma ferramenta estratégica para impulsionar o crescimento da instituição em múltiplas frentes: otimizar a captação de novos alunos, aumentar a retenção dos alunos existentes, fortalecer a presença da marca e engajar a comunidade online.</p><p><strong>A Solução de Design</strong></p><p>Foi implementada uma estratégia de design multifacetada, atuando em pontos críticos da jornada do estudante e da comunicação da marca.</p><ol><li><p><strong>Otimização da Conversão (Aquisição):</strong>A interface da página de inscrições do vestibular foi completamente projetada com foco na otimização do funil de conversão. O resultado direto dessa otimização foi a contribuição para a captação de mais de<strong>800 novos alunos</strong>.</p></li><li><p><strong>Landing Pages Estratégicas:</strong>Foram desenvolvidas Landing Pages dedicadas aos projetos mais estratégicos da instituição, como o lançamento da Escola de Agronegócio e a apresentação do Ecossistema de Negócios Atitus. Essas páginas serviram como ferramentas focadas para comunicar novas iniciativas e capturar o interesse de públicos específicos.</p></li><li><p><strong>Comunicação Visual e Marketing de Conteúdo:</strong>Foram criados e executados os<em>key visuals</em>e a comunicação visual para diversas frentes de marketing. O impacto foi mensurável:</p><ul><li><p><strong>Retenção:</strong>As campanhas de retenção resultaram na rematrícula de centenas de alunos.</p></li><li><p><strong>Engajamento:</strong>O trabalho de design dedicado ao podcast Atitus Talks suportou um crescimento expressivo de<strong>259% em ouvintes</strong>.</p></li></ul></li><li><p><strong>Gestão de Identidade Visual:</strong>Foi realizado um gerenciamento ativo da consistência da identidade visual da marca através da criação de múltiplos conteúdos para diversos canais. Essa consistência contribuiu para um aumento significativo na presença online da marca, com um crescimento de mais de<strong>20.000 seguidores</strong>nas redes sociais.</p></li></ol>Atitus Educação Atitus Educação<p>UI/UX Design</p><p>Desenvolvimento</p><p>Branding</p><p>Editorial</p><p>A Atitus Educação faz parte de um Ecossistema de Educação e Inovação focado em preparar e impulsionar pessoas para o futuro. Com um olhar atento ao mercado, a instituição desenvolveu um modelo educacional inovador, flexível e focado em resultados, formando profissionais capazes de transformar a realidade em que vivem.</p><p><strong>O Desafio</strong></p><p>O desafio era utilizar o design como uma ferramenta estratégica para impulsionar o crescimento da instituição em múltiplas frentes: otimizar a captação de novos alunos, aumentar a retenção dos alunos existentes, fortalecer a presença da marca e engajar a comunidade online.</p><p><strong>A Solução de Design</strong></p><p>Foi implementada uma estratégia de design multifacetada, atuando em pontos críticos da jornada do estudante e da comunicação da marca.</p><ol><li><p><strong>Otimização da Conversão (Aquisição):</strong>A interface da página de inscrições do vestibular foi completamente projetada com foco na otimização do funil de conversão. O resultado direto dessa otimização foi a contribuição para a captação de mais de<strong>800 novos alunos</strong>.</p></li><li><p><strong>Landing Pages Estratégicas:</strong>Foram desenvolvidas Landing Pages dedicadas aos projetos mais estratégicos da instituição, como o lançamento da Escola de Agronegócio e a apresentação do Ecossistema de Negócios Atitus. Essas páginas serviram como ferramentas focadas para comunicar novas iniciativas e capturar o interesse de públicos específicos.</p></li><li><p><strong>Comunicação Visual e Marketing de Conteúdo:</strong>Foram criados e executados os<em>key visuals</em>e a comunicação visual para diversas frentes de marketing. O impacto foi mensurável:</p><ul><li><p><strong>Retenção:</strong>As campanhas de retenção resultaram na rematrícula de centenas de alunos.</p></li><li><p><strong>Engajamento:</strong>O trabalho de design dedicado ao podcast Atitus Talks suportou um crescimento expressivo de<strong>259% em ouvintes</strong>.</p></li></ul></li><li><p><strong>Gestão de Identidade Visual:</strong>Foi realizado um gerenciamento ativo da consistência da identidade visual da marca através da criação de múltiplos conteúdos para diversos canais. Essa consistência contribuiu para um aumento significativo na presença online da marca, com um crescimento de mais de<strong>20.000 seguidores</strong>nas redes sociais.</p></li></ol>Leylaw<p>Anterior</p><p>Anterior</p>Valor Capital Group<p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/atitus-educacao/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/atitus-educacao/cover.jpg","external_url":"","featured_on_home":true,"home_order":1,"portfolio_order":1,"seo_title":"","seo_description":"","published_at":"2026-05-28T20:21:07.399076+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-05-28T20:21:07.399076+00:00"},{"id":"3695850f-5a33-5889-9284-4cb38b7b0b46","legacy_id":"banrisul-app-redesign","legacy_slug":"banrisul-app-redesign","slug":"banrisul-app-redesign","title":"Banrisul | App Redesign","status":"published","categories":["UI/UX Design"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O aplicativo do Banrisul foi lançado em 2016 e tem como objetivo de permitir aos clientes um acesso da conta e dos serviços prestados pelo banco de forma rápida e em qualquer lugar. Em 2019 ele recebeu um redesign. Contudo, as reclamações sobre o app nas lojas digitais eram e ainda são muitas. O banco precisou lançar vídeos curtos no YouTube para explicar como usar as funções do app, devido à péssima experiência do usuário. Por isso, para a disciplina de Design de Interfaces da UFRGS no semestre de 2021/1, foi escolhido o app do Banrisul para trabalhar em um redesign do app com foco na experiência de usuário (UX) a fim de solucionar os problemas de seus usuários e tornar o app mais prático e fácil de ser usado."}]},{"type":"paragraph","content":[{"type":"text","text":"Os usuários apontaram como principais problemas a dificuldade em pagar a fatura de cartão de crédito, o extrato confuso, a dificuldade de encontrar determinadas funções, a falta de sinalização nos botões e a obrigatoriedade de ativar o cartão no caixa eletrônico."}]},{"type":"paragraph","content":[{"type":"text","text":"Na primeira vez em que o usuário entra no app, é oferecido para ele a opção de ativar seu acesso através de biometria facial e envio dos documentos. O app foi reorganizado em duas diferentes seções, de transações e serviços, onde o usuário encontra todas as opções relacionadas. Na tela inicial, é exibido as três funções mais usadas pelo usuário, além de ter um resumo do seu limite de cartão de crédito e saldo, que podem ser ocultos. As telas de extrato e do cartão de crédito foram reorganizadas, tornando-se mais intuitivas e detalhadas."}]},{"type":"paragraph","content":[{"type":"text","text":"UI/UX Design"}]},{"type":"paragraph","content":[{"type":"text","text":"O aplicativo do Banrisul foi lançado em 2016 e tem como objetivo de permitir aos clientes um acesso da conta e dos serviços prestados pelo banco de forma rápida e em qualquer lugar. Em 2019 ele recebeu um redesign. Contudo, as reclamações sobre o app nas lojas digitais eram e ainda são muitas. O banco precisou lançar vídeos curtos no YouTube para explicar como usar as funções do app, devido à péssima experiência do usuário. Por isso, para a disciplina de Design de Interfaces da UFRGS no semestre de 2021/1, foi escolhido o app do Banrisul para trabalhar em um redesign do app com foco na experiência de usuário (UX) a fim de solucionar os problemas de seus usuários e tornar o app mais prático e fácil de ser usado."}]},{"type":"paragraph","content":[{"type":"text","text":"Os usuários apontaram como principais problemas a dificuldade em pagar a fatura de cartão de crédito, o extrato confuso, a dificuldade de encontrar determinadas funções, a falta de sinalização nos botões e a obrigatoriedade de ativar o cartão no caixa eletrônico."}]},{"type":"paragraph","content":[{"type":"text","text":"Na primeira vez em que o usuário entra no app, é oferecido para ele a opção de ativar seu acesso através de biometria facial e envio dos documentos. O app foi reorganizado em duas diferentes seções, de transações e serviços, onde o usuário encontra todas as opções relacionadas. Na tela inicial, é exibido as três funções mais usadas pelo usuário, além de ter um resumo do seu limite de cartão de crédito e saldo, que podem ser ocultos. As telas de extrato e do cartão de crédito foram reorganizadas, tornando-se mais intuitivas e detalhadas."}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p>O aplicativo do Banrisul foi lançado em 2016 e tem como objetivo de permitir aos clientes um acesso da conta e dos serviços prestados pelo banco de forma rápida e em qualquer lugar. Em 2019 ele recebeu um redesign. Contudo, as reclamações sobre o app nas lojas digitais eram e ainda são muitas. O banco precisou lançar vídeos curtos no YouTube para explicar como usar as funções do app, devido à péssima experiência do usuário. Por isso, para a disciplina de Design de Interfaces da UFRGS no semestre de 2021/1, foi escolhido o app do Banrisul para trabalhar em um redesign do app com foco na experiência de usuário (UX) a fim de solucionar os problemas de seus usuários e tornar o app mais prático e fácil de ser usado.</p><p>Os usuários apontaram como principais problemas a dificuldade em pagar a fatura de cartão de crédito, o extrato confuso, a dificuldade de encontrar determinadas funções, a falta de sinalização nos botões e a obrigatoriedade de ativar o cartão no caixa eletrônico.</p><p>Na primeira vez em que o usuário entra no app, é oferecido para ele a opção de ativar seu acesso através de biometria facial e envio dos documentos. O app foi reorganizado em duas diferentes seções, de transações e serviços, onde o usuário encontra todas as opções relacionadas. Na tela inicial, é exibido as três funções mais usadas pelo usuário, além de ter um resumo do seu limite de cartão de crédito e saldo, que podem ser ocultos. As telas de extrato e do cartão de crédito foram reorganizadas, tornando-se mais intuitivas e detalhadas.</p>Banrisul | App Redesign Banrisul | App Redesign<p>UI/UX Design</p><p>O aplicativo do Banrisul foi lançado em 2016 e tem como objetivo de permitir aos clientes um acesso da conta e dos serviços prestados pelo banco de forma rápida e em qualquer lugar. Em 2019 ele recebeu um redesign. Contudo, as reclamações sobre o app nas lojas digitais eram e ainda são muitas. O banco precisou lançar vídeos curtos no YouTube para explicar como usar as funções do app, devido à péssima experiência do usuário. Por isso, para a disciplina de Design de Interfaces da UFRGS no semestre de 2021/1, foi escolhido o app do Banrisul para trabalhar em um redesign do app com foco na experiência de usuário (UX) a fim de solucionar os problemas de seus usuários e tornar o app mais prático e fácil de ser usado.</p><p>Os usuários apontaram como principais problemas a dificuldade em pagar a fatura de cartão de crédito, o extrato confuso, a dificuldade de encontrar determinadas funções, a falta de sinalização nos botões e a obrigatoriedade de ativar o cartão no caixa eletrônico.</p><p>Na primeira vez em que o usuário entra no app, é oferecido para ele a opção de ativar seu acesso através de biometria facial e envio dos documentos. O app foi reorganizado em duas diferentes seções, de transações e serviços, onde o usuário encontra todas as opções relacionadas. Na tela inicial, é exibido as três funções mais usadas pelo usuário, além de ter um resumo do seu limite de cartão de crédito e saldo, que podem ser ocultos. As telas de extrato e do cartão de crédito foram reorganizadas, tornando-se mais intuitivas e detalhadas.</p>Vacinas | Infográfico<p>Anterior</p><p>Anterior</p>DEMIP<p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/banrisul-app-redesign/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/banrisul-app-redesign/cover.jpg","external_url":"","featured_on_home":false,"home_order":999,"portfolio_order":10,"seo_title":"","seo_description":"","published_at":"2026-05-28T20:21:07.399076+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-05-28T20:21:07.399076+00:00"},{"id":"9247d30f-0a43-5a9b-bf56-7ced62a678c7","legacy_id":"blenduca","legacy_slug":"blenduca","slug":"blenduca","title":"Blenduca","status":"published","categories":["UI/UX Design","Desenvolvimento","Branding","Editorial"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Blenduca é uma empresa de inovação educacional que oferece um portfólio completo de serviços, incluindo mentorias, consultorias e soluções de tecnologia. O seu objetivo é capacitar experts de conhecimento (como especialistas, coaches e infoprodutores) a se tornarem também experts de negócios, fornecendo as ferramentas e a estratégia para o sucesso."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O principal desafio era criar um ecossistema de design coeso e escalável que pudesse suportar tanto as necessidades de marketing da própria Blenduca quanto o sucesso dos produtos digitais de seus clientes. A comunicação visual precisava ser consistente em múltiplos pontos de contato — desde o primeiro anúncio nas redes sociais até a plataforma de ensino final — para construir uma marca forte, profissional e confiável."}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução: Um Design System Integrado"}]},{"type":"paragraph","content":[{"type":"text","text":"Para atender a essa demanda complexa, foi desenvolvida uma solução de design 360°, que abrangeu desde a criação de materiais de marketing até o design de produto da plataforma tecnológica da empresa. O trabalho foi dividido em três frentes principais:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Identidade Visual para Produtos e Lançamentos&nbsp;"}]},{"type":"paragraph","content":[{"type":"text","text":"Para cada novo produto e evento da Blenduca, foi criada uma identidade visual única, porém alinhada à marca-mãe. Isso incluiu o design de apresentações de produto, key visuals e landing pages de alta conversão, seguindo um cronograma estratégico de lançamentos para maximizar o impacto no mercado."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Design da Plataforma de EAD (B'Tech)&nbsp;"}]},{"type":"paragraph","content":[{"type":"text","text":"O coração da solução tecnológica da Blenduca é sua plataforma de ensino à distância. Foi projetada toda a identidade visual e a interface do usuário (UI) da plataforma, criando uma experiência \"estilo Netflix\" que é moderna e intuitiva. O trabalho incluiu o design de um sistema de capas (thumbnails) para as aulas, garantindo uma navegação visualmente rica e organizada para o aluno final."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Materiais de Marketing e Comunicação&nbsp;"}]},{"type":"paragraph","content":[{"type":"text","text":"Para garantir a presença e o crescimento da marca, foi desenvolvida uma vasta gama de materiais de comunicação, tanto digitais quanto impressos. Isso incluiu posts para redes sociais (orgânicos e pagos), banners digitais, outdoors, folders e backdrops para eventos, assegurando uma mensagem visual consistente e profissional em todos os canais."}]},{"type":"paragraph","content":[{"type":"text","text":"O Impacto"}]},{"type":"paragraph","content":[{"type":"text","text":"A criação de um ecossistema de design coeso e profissional foi fundamental para posicionar a Blenduca como uma autoridade no mercado. Mais importante, as ferramentas e os produtos digitais desenhados (plataformas e funis de vendas) foram essenciais para o sucesso dos clientes da empresa, contribuindo para um ecossistema que já&nbsp;acelerou mais de 200 negócios de conhecimento&nbsp;e gerou&nbsp;mais de R$40 milhões em receita&nbsp;para esses clientes."}]},{"type":"paragraph","content":[{"type":"text","text":"UI/UX Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Desenvolvimento"}]},{"type":"paragraph","content":[{"type":"text","text":"Branding"}]},{"type":"paragraph","content":[{"type":"text","text":"Editorial"}]},{"type":"paragraph","content":[{"type":"text","text":"Acessar website"}]},{"type":"paragraph","content":[{"type":"text","text":"Acessar website"}]},{"type":"paragraph","content":[{"type":"text","text":"Acessar website"}]},{"type":"paragraph","content":[{"type":"text","text":"A Blenduca é uma empresa de inovação educacional que oferece um portfólio completo de serviços, incluindo mentorias, consultorias e soluções de tecnologia. O seu objetivo é capacitar experts de conhecimento (como especialistas, coaches e infoprodutores) a se tornarem também experts de negócios, fornecendo as ferramentas e a estratégia para o sucesso."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O principal desafio era criar um ecossistema de design coeso e escalável que pudesse suportar tanto as necessidades de marketing da própria Blenduca quanto o sucesso dos produtos digitais de seus clientes. A comunicação visual precisava ser consistente em múltiplos pontos de contato — desde o primeiro anúncio nas redes sociais até a plataforma de ensino final — para construir uma marca forte, profissional e confiável."}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução: Um Design System Integrado"}]},{"type":"paragraph","content":[{"type":"text","text":"Para atender a essa demanda complexa, foi desenvolvida uma solução de design 360°, que abrangeu desde a criação de materiais de marketing até o design de produto da plataforma tecnológica da empresa. O trabalho foi dividido em três frentes principais:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Identidade Visual para Produtos e Lançamentos&nbsp;"}]},{"type":"paragraph","content":[{"type":"text","text":"Para cada novo produto e evento da Blenduca, foi criada uma identidade visual única, porém alinhada à marca-mãe. Isso incluiu o design de apresentações de produto, key visuals e landing pages de alta conversão, seguindo um cronograma estratégico de lançamentos para maximizar o impacto no mercado."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Design da Plataforma de EAD (B'Tech)&nbsp;"}]},{"type":"paragraph","content":[{"type":"text","text":"O coração da solução tecnológica da Blenduca é sua plataforma de ensino à distância. Foi projetada toda a identidade visual e a interface do usuário (UI) da plataforma, criando uma experiência \"estilo Netflix\" que é moderna e intuitiva. O trabalho incluiu o design de um sistema de capas (thumbnails) para as aulas, garantindo uma navegação visualmente rica e organizada para o aluno final."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Materiais de Marketing e Comunicação&nbsp;"}]},{"type":"paragraph","content":[{"type":"text","text":"Para garantir a presença e o crescimento da marca, foi desenvolvida uma vasta gama de materiais de comunicação, tanto digitais quanto impressos. Isso incluiu posts para redes sociais (orgânicos e pagos), banners digitais, outdoors, folders e backdrops para eventos, assegurando uma mensagem visual consistente e profissional em todos os canais."}]},{"type":"paragraph","content":[{"type":"text","text":"O Impacto"}]},{"type":"paragraph","content":[{"type":"text","text":"A criação de um ecossistema de design coeso e profissional foi fundamental para posicionar a Blenduca como uma autoridade no mercado. Mais importante, as ferramentas e os produtos digitais desenhados (plataformas e funis de vendas) foram essenciais para o sucesso dos clientes da empresa, contribuindo para um ecossistema que já&nbsp;acelerou mais de 200 negócios de conhecimento&nbsp;e gerou&nbsp;mais de R$40 milhões em receita&nbsp;para esses clientes."}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p>A Blenduca é uma empresa de inovação educacional que oferece um portfólio completo de serviços, incluindo mentorias, consultorias e soluções de tecnologia. O seu objetivo é capacitar experts de conhecimento (como especialistas, coaches e infoprodutores) a se tornarem também experts de negócios, fornecendo as ferramentas e a estratégia para o sucesso.</p><p><strong>O Desafio</strong></p><p>O principal desafio era criar um ecossistema de design coeso e escalável que pudesse suportar tanto as necessidades de marketing da própria Blenduca quanto o sucesso dos produtos digitais de seus clientes. A comunicação visual precisava ser consistente em múltiplos pontos de contato — desde o primeiro anúncio nas redes sociais até a plataforma de ensino final — para construir uma marca forte, profissional e confiável.</p><p><strong>A Solução: Um Design System Integrado</strong></p><p>Para atender a essa demanda complexa, foi desenvolvida uma solução de design 360°, que abrangeu desde a criação de materiais de marketing até o design de produto da plataforma tecnológica da empresa. O trabalho foi dividido em três frentes principais:</p><p><strong>1. Identidade Visual para Produtos e Lançamentos&nbsp;</strong></p><p>Para cada novo produto e evento da Blenduca, foi criada uma identidade visual única, porém alinhada à marca-mãe. Isso incluiu o design de apresentações de produto, key visuals e landing pages de alta conversão, seguindo um cronograma estratégico de lançamentos para maximizar o impacto no mercado.</p><p><strong>2. Design da Plataforma de EAD (B'Tech)&nbsp;</strong></p><p>O coração da solução tecnológica da Blenduca é sua plataforma de ensino à distância. Foi projetada toda a identidade visual e a interface do usuário (UI) da plataforma, criando uma experiência \"estilo Netflix\" que é moderna e intuitiva. O trabalho incluiu o design de um sistema de capas (thumbnails) para as aulas, garantindo uma navegação visualmente rica e organizada para o aluno final.</p><p><strong>3. Materiais de Marketing e Comunicação&nbsp;</strong></p><p>Para garantir a presença e o crescimento da marca, foi desenvolvida uma vasta gama de materiais de comunicação, tanto digitais quanto impressos. Isso incluiu posts para redes sociais (orgânicos e pagos), banners digitais, outdoors, folders e backdrops para eventos, assegurando uma mensagem visual consistente e profissional em todos os canais.</p><p><strong>O Impacto</strong></p><p>A criação de um ecossistema de design coeso e profissional foi fundamental para posicionar a Blenduca como uma autoridade no mercado. Mais importante, as ferramentas e os produtos digitais desenhados (plataformas e funis de vendas) foram essenciais para o sucesso dos clientes da empresa, contribuindo para um ecossistema que já&nbsp;acelerou mais de 200 negócios de conhecimento&nbsp;e gerou&nbsp;mais de R$40 milhões em receita&nbsp;para esses clientes.</p>Blenduca Blenduca<p>UI/UX Design</p><p>Desenvolvimento</p><p>Branding</p><p>Editorial</p><p>Acessar website</p><p>Acessar website</p><p>Acessar website</p><p>A Blenduca é uma empresa de inovação educacional que oferece um portfólio completo de serviços, incluindo mentorias, consultorias e soluções de tecnologia. O seu objetivo é capacitar experts de conhecimento (como especialistas, coaches e infoprodutores) a se tornarem também experts de negócios, fornecendo as ferramentas e a estratégia para o sucesso.</p><p><strong>O Desafio</strong></p><p>O principal desafio era criar um ecossistema de design coeso e escalável que pudesse suportar tanto as necessidades de marketing da própria Blenduca quanto o sucesso dos produtos digitais de seus clientes. A comunicação visual precisava ser consistente em múltiplos pontos de contato — desde o primeiro anúncio nas redes sociais até a plataforma de ensino final — para construir uma marca forte, profissional e confiável.</p><p><strong>A Solução: Um Design System Integrado</strong></p><p>Para atender a essa demanda complexa, foi desenvolvida uma solução de design 360°, que abrangeu desde a criação de materiais de marketing até o design de produto da plataforma tecnológica da empresa. O trabalho foi dividido em três frentes principais:</p><p><strong>1. Identidade Visual para Produtos e Lançamentos&nbsp;</strong></p><p>Para cada novo produto e evento da Blenduca, foi criada uma identidade visual única, porém alinhada à marca-mãe. Isso incluiu o design de apresentações de produto, key visuals e landing pages de alta conversão, seguindo um cronograma estratégico de lançamentos para maximizar o impacto no mercado.</p><p><strong>2. Design da Plataforma de EAD (B'Tech)&nbsp;</strong></p><p>O coração da solução tecnológica da Blenduca é sua plataforma de ensino à distância. Foi projetada toda a identidade visual e a interface do usuário (UI) da plataforma, criando uma experiência \"estilo Netflix\" que é moderna e intuitiva. O trabalho incluiu o design de um sistema de capas (thumbnails) para as aulas, garantindo uma navegação visualmente rica e organizada para o aluno final.</p><p><strong>3. Materiais de Marketing e Comunicação&nbsp;</strong></p><p>Para garantir a presença e o crescimento da marca, foi desenvolvida uma vasta gama de materiais de comunicação, tanto digitais quanto impressos. Isso incluiu posts para redes sociais (orgânicos e pagos), banners digitais, outdoors, folders e backdrops para eventos, assegurando uma mensagem visual consistente e profissional em todos os canais.</p><p><strong>O Impacto</strong></p><p>A criação de um ecossistema de design coeso e profissional foi fundamental para posicionar a Blenduca como uma autoridade no mercado. Mais importante, as ferramentas e os produtos digitais desenhados (plataformas e funis de vendas) foram essenciais para o sucesso dos clientes da empresa, contribuindo para um ecossistema que já&nbsp;acelerou mais de 200 negócios de conhecimento&nbsp;e gerou&nbsp;mais de R$40 milhões em receita&nbsp;para esses clientes.</p>Você Marca<p>Anterior</p><p>Anterior</p>Capri Housing<p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/blenduca/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/blenduca/cover.jpg","external_url":"https://www.blenduca.com.br","featured_on_home":false,"home_order":999,"portfolio_order":30,"seo_title":"","seo_description":"","published_at":"2026-06-01T14:19:37.302014+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-06-01T14:19:37.302014+00:00"},{"id":"9e8c302d-40bf-5411-84a5-0ff086387f7b","legacy_id":"bu1ld","legacy_slug":"bu1ld","slug":"bu1ld","title":"BU1LD","status":"published","categories":["UI/UX Design","Desenvolvimento"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A B1ld é uma empresa especializada na criação de produtos, projetos e experiências memoráveis, conectando desenvolvedores, plataformas, comunidades e marcas."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O desafio era criar uma landing page que servisse como o cartão de visitas digital da B1ld. A página precisava apresentar a empresa, seus fundadores, parceiros e redes sociais de forma clara e profissional. No entanto, um requisito fundamental era que o design incorporasse uma forte referência visual do universo dos games , refletindo a natureza das experiências que a empresa cria e, potencialmente, o interesse de seu público-alvo (desenvolvedores e comunidades)."}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução de Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Foi desenvolvida uma landing page que equilibra a informação corporativa com uma estética inspirada em games, resultando em uma experiência de usuário envolvente e impactante."}]},{"type":"paragraph","content":[{"type":"text","text":"A solução se concentrou em traduzir conceitos criativos em uma interface digital que fosse ao mesmo tempo visualmente atraente e funcional . A integração da estética gamer foi realizada através da paleta de cores, tipografia, elementos gráficos e microinterações, criando uma atmosfera única que diferencia a B1ld no mercado, ao mesmo tempo em que apresenta de forma clara e organizada as informações essenciais sobre a empresa e seus stakeholders."}]},{"type":"paragraph","content":[{"type":"text","text":"UI/UX Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Desenvolvimento"}]},{"type":"paragraph","content":[{"type":"text","text":"A B1ld é uma empresa especializada na criação de produtos, projetos e experiências memoráveis, conectando desenvolvedores, plataformas, comunidades e marcas."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O desafio era criar uma landing page que servisse como o cartão de visitas digital da B1ld. A página precisava apresentar a empresa, seus fundadores, parceiros e redes sociais de forma clara e profissional. No entanto, um requisito fundamental era que o design incorporasse uma forte referência visual do universo dos games , refletindo a natureza das experiências que a empresa cria e, potencialmente, o interesse de seu público-alvo (desenvolvedores e comunidades)."}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução de Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Foi desenvolvida uma landing page que equilibra a informação corporativa com uma estética inspirada em games, resultando em uma experiência de usuário envolvente e impactante."}]},{"type":"paragraph","content":[{"type":"text","text":"A solução se concentrou em traduzir conceitos criativos em uma interface digital que fosse ao mesmo tempo visualmente atraente e funcional . A integração da estética gamer foi realizada através da paleta de cores, tipografia, elementos gráficos e microinterações, criando uma atmosfera única que diferencia a B1ld no mercado, ao mesmo tempo em que apresenta de forma clara e organizada as informações essenciais sobre a empresa e seus stakeholders."}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p>A B1ld é uma empresa especializada na criação de produtos, projetos e experiências memoráveis, conectando desenvolvedores, plataformas, comunidades e marcas.</p><p><strong>O Desafio</strong></p><p>O desafio era criar uma landing page que servisse como o cartão de visitas digital da B1ld. A página precisava apresentar a empresa, seus fundadores, parceiros e redes sociais de forma clara e profissional. No entanto, um requisito fundamental era que o design incorporasse uma<strong>forte referência visual do universo dos games</strong>, refletindo a natureza das experiências que a empresa cria e, potencialmente, o interesse de seu público-alvo (desenvolvedores e comunidades).</p><p><strong>A Solução de Design</strong></p><p>Foi desenvolvida uma landing page que equilibra a informação corporativa com uma estética inspirada em games, resultando em uma experiência de usuário envolvente e impactante.</p><p>A solução se concentrou em traduzir conceitos criativos em uma interface digital que fosse ao mesmo tempo<strong>visualmente atraente e funcional</strong>. A integração da estética gamer foi realizada através da paleta de cores, tipografia, elementos gráficos e microinterações, criando uma atmosfera única que diferencia a B1ld no mercado, ao mesmo tempo em que apresenta de forma clara e organizada as informações essenciais sobre a empresa e seus stakeholders.</p>BU1LD BU1LD<p>UI/UX Design</p><p>Desenvolvimento</p><p>A B1ld é uma empresa especializada na criação de produtos, projetos e experiências memoráveis, conectando desenvolvedores, plataformas, comunidades e marcas.</p><p><strong>O Desafio</strong></p><p>O desafio era criar uma landing page que servisse como o cartão de visitas digital da B1ld. A página precisava apresentar a empresa, seus fundadores, parceiros e redes sociais de forma clara e profissional. No entanto, um requisito fundamental era que o design incorporasse uma<strong>forte referência visual do universo dos games</strong>, refletindo a natureza das experiências que a empresa cria e, potencialmente, o interesse de seu público-alvo (desenvolvedores e comunidades).</p><p><strong>A Solução de Design</strong></p><p>Foi desenvolvida uma landing page que equilibra a informação corporativa com uma estética inspirada em games, resultando em uma experiência de usuário envolvente e impactante.</p><p>A solução se concentrou em traduzir conceitos criativos em uma interface digital que fosse ao mesmo tempo<strong>visualmente atraente e funcional</strong>. A integração da estética gamer foi realizada através da paleta de cores, tipografia, elementos gráficos e microinterações, criando uma atmosfera única que diferencia a B1ld no mercado, ao mesmo tempo em que apresenta de forma clara e organizada as informações essenciais sobre a empresa e seus stakeholders.</p>Capri Housing<p>Anterior</p><p>Anterior</p>Portal do Aluno UFRGS<p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/bu1ld/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/bu1ld/cover.jpg","external_url":"","featured_on_home":false,"home_order":999,"portfolio_order":11,"seo_title":"","seo_description":"","published_at":"2026-05-28T20:21:07.399076+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-05-28T20:21:07.399076+00:00"},{"id":"15d18664-aeac-5e45-bae4-f932b7403847","legacy_id":"calendário-impresul-2023","legacy_slug":"calendário-impresul-2023","slug":"calendário-impresul-2023","title":"Calendário Impresul 2023","status":"published","categories":["Editorial"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"“Os lugares que você vai se transformam em uma parte de você,[…]” -Anita Desai O calendário da Impresul do ano de 2023 possui uma interessante dinâmica que é conhecer os lugares mais fantásticos já explorados em nosso planeta pela espécie humana, bem como trazer a você informações sobre eles através da tecnologia e lhe transportar para esse ambiente por meio de músicas selecionadas. A Impresul entende, como gráfica, que o mundo está cada vez mais moderno e a sua missão, bem como o seu compromisso, é passar as novas tecnologias para o papel que roda em suas impressoras. Com a curadoria de fotos de Eurico Salis, participação de seis fotógrafos renomados, design e tratamento de imagem desenvolvido pelos Studios Meca e produção em no maior parque gráfico do sul do Brasil, esperamos trazer a você não apenas um simples calendário, mas, uma obra que pode lhe expandir horizontes unindo o impresso e o mundo virtual, abrindo espaço para novas ideias."}]},{"type":"paragraph","content":[{"type":"text","text":"Editorial"}]},{"type":"paragraph","content":[{"type":"text","text":"“Os lugares que você vai se transformam em uma parte de você,[…]” -Anita Desai O calendário da Impresul do ano de 2023 possui uma interessante dinâmica que é conhecer os lugares mais fantásticos já explorados em nosso planeta pela espécie humana, bem como trazer a você informações sobre eles através da tecnologia e lhe transportar para esse ambiente por meio de músicas selecionadas. A Impresul entende, como gráfica, que o mundo está cada vez mais moderno e a sua missão, bem como o seu compromisso, é passar as novas tecnologias para o papel que roda em suas impressoras. Com a curadoria de fotos de Eurico Salis, participação de seis fotógrafos renomados, design e tratamento de imagem desenvolvido pelos Studios Meca e produção em no maior parque gráfico do sul do Brasil, esperamos trazer a você não apenas um simples calendário, mas, uma obra que pode lhe expandir horizontes unindo o impresso e o mundo virtual, abrindo espaço para novas ideias."}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p><strong>“Os lugares que você vai se transformam em uma parte de você,[…]”</strong><br>-Anita Desai<br><br>O calendário da Impresul do ano de 2023 possui uma interessante dinâmica que é conhecer os lugares mais fantásticos já explorados em nosso planeta pela espécie humana, bem como trazer a você informações sobre eles através da tecnologia e lhe transportar para esse ambiente por meio de músicas selecionadas.<br><br>A Impresul entende, como gráfica, que o mundo está cada vez mais moderno e a sua missão, bem como o seu compromisso, é passar as novas tecnologias para o papel que roda em suas impressoras.<br><br>Com a curadoria de fotos de Eurico Salis, participação de seis fotógrafos renomados, design e tratamento de imagem desenvolvido pelos Studios Meca e produção em no maior parque gráfico do sul do Brasil, esperamos trazer a você não apenas um simples calendário, mas, uma obra que pode lhe expandir horizontes unindo o impresso e o mundo virtual, abrindo espaço para novas ideias.</p>Calendário Impresul 2023 Calendário Impresul 2023<p>Editorial</p><p><strong>“Os lugares que você vai se transformam em uma parte de você,[…]”</strong><br>-Anita Desai<br><br>O calendário da Impresul do ano de 2023 possui uma interessante dinâmica que é conhecer os lugares mais fantásticos já explorados em nosso planeta pela espécie humana, bem como trazer a você informações sobre eles através da tecnologia e lhe transportar para esse ambiente por meio de músicas selecionadas.<br><br>A Impresul entende, como gráfica, que o mundo está cada vez mais moderno e a sua missão, bem como o seu compromisso, é passar as novas tecnologias para o papel que roda em suas impressoras.<br><br>Com a curadoria de fotos de Eurico Salis, participação de seis fotógrafos renomados, design e tratamento de imagem desenvolvido pelos Studios Meca e produção em no maior parque gráfico do sul do Brasil, esperamos trazer a você não apenas um simples calendário, mas, uma obra que pode lhe expandir horizontes unindo o impresso e o mundo virtual, abrindo espaço para novas ideias.</p>JAQ H2<p>Anterior</p><p>Anterior</p>Click Impresso<p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/calendario-impresul-2023/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/calendario-impresul-2023/cover.jpg","external_url":"","featured_on_home":false,"home_order":999,"portfolio_order":12,"seo_title":"","seo_description":"","published_at":"2026-05-28T20:21:07.399076+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-05-28T20:21:07.399076+00:00"},{"id":"38403d28-1fdb-5004-ace0-c142fc5c2f71","legacy_id":"calendário-impresul-2024","legacy_slug":"calendário-impresul-2024","slug":"calendário-impresul-2024","title":"Calendário Impresul 2024","status":"published","categories":["Editorial"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Com o passar dos anos a tecnologia vem avançando e servindo de apoio ao ser humano para criar, aprimorar e ter novas visões sobre o mundo. Mas tem uma coisa que a inteligência artificial nunca terá: a humanidade ! A Impresul usou a tecnologia para ressaltar o olhar humano e mostrar o quanto precisamos desse toque de sensibilidade que o artista oferece. Adotamos como dinâmica o uso de QR Codes e faixas musicais selecionadas para trazer a você, nosso cliente, uma maior interatividade com esse material. Através dos meses nós convidamos você a embarcar em uma viagem por Paris, a cidade luz, capital da França."}]},{"type":"paragraph","content":[{"type":"text","text":"Editorial"}]},{"type":"paragraph","content":[{"type":"text","text":"Com o passar dos anos a tecnologia vem avançando e servindo de apoio ao ser humano para criar, aprimorar e ter novas visões sobre o mundo. Mas tem uma coisa que a inteligência artificial nunca terá: a humanidade ! A Impresul usou a tecnologia para ressaltar o olhar humano e mostrar o quanto precisamos desse toque de sensibilidade que o artista oferece. Adotamos como dinâmica o uso de QR Codes e faixas musicais selecionadas para trazer a você, nosso cliente, uma maior interatividade com esse material. Através dos meses nós convidamos você a embarcar em uma viagem por Paris, a cidade luz, capital da França."}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p>Com o passar dos anos a tecnologia vem avançando e servindo de apoio ao ser humano para criar, aprimorar e ter novas visões sobre o mundo. Mas tem uma coisa que a<strong>inteligência artificial</strong>nunca terá: a<strong>humanidade</strong>! A Impresul usou a tecnologia para ressaltar o<strong>olhar humano</strong>e mostrar o quanto precisamos desse<strong>toque de sensibilidade</strong>que o artista oferece.<br><br>Adotamos como dinâmica o uso de<strong>QR Codes</strong>e<strong>faixas musicais</strong>selecionadas para trazer a você, nosso cliente, uma maior interatividade com esse material. Através dos meses nós convidamos você a embarcar em uma viagem por Paris, a cidade luz, capital da França.</p>Calendário Impresul 2024 Calendário Impresul 2024<p>Editorial</p><p>Com o passar dos anos a tecnologia vem avançando e servindo de apoio ao ser humano para criar, aprimorar e ter novas visões sobre o mundo. Mas tem uma coisa que a<strong>inteligência artificial</strong>nunca terá: a<strong>humanidade</strong>! A Impresul usou a tecnologia para ressaltar o<strong>olhar humano</strong>e mostrar o quanto precisamos desse<strong>toque de sensibilidade</strong>que o artista oferece.<br><br>Adotamos como dinâmica o uso de<strong>QR Codes</strong>e<strong>faixas musicais</strong>selecionadas para trazer a você, nosso cliente, uma maior interatividade com esse material. Através dos meses nós convidamos você a embarcar em uma viagem por Paris, a cidade luz, capital da França.</p>Click Impresso<p>Anterior</p><p>Anterior</p>A Primeira Segunda-Feira<p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/calendario-impresul-2024/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/calendario-impresul-2024/cover.jpg","external_url":"","featured_on_home":false,"home_order":999,"portfolio_order":13,"seo_title":"","seo_description":"","published_at":"2026-05-28T20:21:07.399076+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-05-28T20:21:07.399076+00:00"},{"id":"67091233-1416-58e1-82bf-3219f184e628","legacy_id":"candy-dates","legacy_slug":"candy-dates","slug":"candy-dates","title":"Candy Dates","status":"published","categories":["UI/UX Design","Desenvolvimento"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Smood Sweets é uma marca criada por três amigos europeus com a missão de oferecer doces saborosos, naturais e \"sem culpa\". Seu produto de lançamento, os Candy Dates, são tâmaras recheadas com combinações frutadas, com uma pegada nostálgica e ingredientes limpos. O desafio era criar uma loja virtual (e-commerce) na plataforma Shopify que não apenas vendesse o produto, mas que também transmitisse a essência leve, funcional e irresistível da marca."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio: Traduzir Sabor em Pixels"}]},{"type":"paragraph","content":[{"type":"text","text":"O principal desafio de design era transformar a atmosfera \"divertida, leve e acolhedora\" da identidade visual, fornecida pelo cliente, em uma experiência de compra digital coesa. Para um produto novo e de consumo por impulso, a experiência precisava resolver três pontos-chave:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Criar Apetite Visual: A interface deveria ser visualmente atraente o suficiente para fazer os visitantes desejarem provar um produto que nunca viram antes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Comunicar o Valor: O design precisava destacar de forma clara e rápida os diferenciais do produto (natural, sem culpa, ingredientes simples)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Simplificar a Conversão: O processo de compra, do clique inicial ao checkout, deveria ser extremamente simples, rápido e intuitivo para minimizar qualquer atrito e maximizar as vendas."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto foi guiado por um processo iterativo para garantir que cada decisão de design estivesse alinhada com os objetivos da marca e as necessidades dos usuários."}]},{"type":"paragraph","content":[{"type":"text","text":"1. Imersão na Marca e Arquitetura O ponto de partida foi uma imersão nas referências visuais e na identidade enviadas pelo cliente. A partir daí, estruturamos a arquitetura da informação do site, definindo as páginas essenciais (Home, Página de Produto, Carrinho, Checkout) e o fluxo de navegação mais simples possível para o usuário."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Prototipagem e Testes Iterativos Criamos protótipos interativos no Figma para simular a experiência de compra completa. Realizamos diversos testes de usabilidade com foco na jornada principal do cliente: encontrar um produto, entender seus ingredientes, adicioná-lo ao carrinho e finalizar a compra. O feedback coletado nesses testes foi crucial para refinar a disposição dos elementos, a clareza dos botões (CTAs) e a fluidez geral do processo."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Design Visual (UI) e Refinamento Com a estrutura e o fluxo validados, aplicamos a identidade visual da marca na interface de alta fidelidade. O foco foi usar a paleta de cores, tipografia e imagens de alta qualidade para criar uma atmosfera convidativa e \"saborosa\". Cada detalhe, desde os ícones até a apresentação das informações nutricionais, foi desenhado para ser intuitivo, bonito e alinhado com a promessa de um doce natural e prazeroso."}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução"}]},{"type":"paragraph","content":[{"type":"text","text":"O resultado é uma loja virtual na plataforma Shopify que é tão agradável quanto os próprios Candy Dates. A solução final entregue foi:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Um e-commerce leve e funcional , com design responsivo e otimizado para compras via mobile."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Páginas de produto claras e atraentes , que destacam os ingredientes naturais e incentivam a compra."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Um fluxo de checkout simplificado , projetado para reduzir o abandono de carrinho e garantir uma experiência de compra positiva."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A plataforma digital traduz com sucesso a essência da Smood Sweets, oferecendo uma experiência de compra que é, ao mesmo tempo, divertida, confiável e irresistível."}]},{"type":"paragraph","content":[{"type":"text","text":"UI/UX Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Desenvolvimento"}]},{"type":"paragraph","content":[{"type":"text","text":"A Smood Sweets é uma marca criada por três amigos europeus com a missão de oferecer doces saborosos, naturais e \"sem culpa\". Seu produto de lançamento, os Candy Dates, são tâmaras recheadas com combinações frutadas, com uma pegada nostálgica e ingredientes limpos. O desafio era criar uma loja virtual (e-commerce) na plataforma Shopify que não apenas vendesse o produto, mas que também transmitisse a essência leve, funcional e irresistível da marca."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio: Traduzir Sabor em Pixels"}]},{"type":"paragraph","content":[{"type":"text","text":"O principal desafio de design era transformar a atmosfera \"divertida, leve e acolhedora\" da identidade visual, fornecida pelo cliente, em uma experiência de compra digital coesa. Para um produto novo e de consumo por impulso, a experiência precisava resolver três pontos-chave:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Criar Apetite Visual: A interface deveria ser visualmente atraente o suficiente para fazer os visitantes desejarem provar um produto que nunca viram antes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Comunicar o Valor: O design precisava destacar de forma clara e rápida os diferenciais do produto (natural, sem culpa, ingredientes simples)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Simplificar a Conversão: O processo de compra, do clique inicial ao checkout, deveria ser extremamente simples, rápido e intuitivo para minimizar qualquer atrito e maximizar as vendas."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto foi guiado por um processo iterativo para garantir que cada decisão de design estivesse alinhada com os objetivos da marca e as necessidades dos usuários."}]},{"type":"paragraph","content":[{"type":"text","text":"1. Imersão na Marca e Arquitetura O ponto de partida foi uma imersão nas referências visuais e na identidade enviadas pelo cliente. A partir daí, estruturamos a arquitetura da informação do site, definindo as páginas essenciais (Home, Página de Produto, Carrinho, Checkout) e o fluxo de navegação mais simples possível para o usuário."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Prototipagem e Testes Iterativos Criamos protótipos interativos no Figma para simular a experiência de compra completa. Realizamos diversos testes de usabilidade com foco na jornada principal do cliente: encontrar um produto, entender seus ingredientes, adicioná-lo ao carrinho e finalizar a compra. O feedback coletado nesses testes foi crucial para refinar a disposição dos elementos, a clareza dos botões (CTAs) e a fluidez geral do processo."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Design Visual (UI) e Refinamento Com a estrutura e o fluxo validados, aplicamos a identidade visual da marca na interface de alta fidelidade. O foco foi usar a paleta de cores, tipografia e imagens de alta qualidade para criar uma atmosfera convidativa e \"saborosa\". Cada detalhe, desde os ícones até a apresentação das informações nutricionais, foi desenhado para ser intuitivo, bonito e alinhado com a promessa de um doce natural e prazeroso."}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução"}]},{"type":"paragraph","content":[{"type":"text","text":"O resultado é uma loja virtual na plataforma Shopify que é tão agradável quanto os próprios Candy Dates. A solução final entregue foi:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Um e-commerce leve e funcional , com design responsivo e otimizado para compras via mobile."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Páginas de produto claras e atraentes , que destacam os ingredientes naturais e incentivam a compra."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Um fluxo de checkout simplificado , projetado para reduzir o abandono de carrinho e garantir uma experiência de compra positiva."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A plataforma digital traduz com sucesso a essência da Smood Sweets, oferecendo uma experiência de compra que é, ao mesmo tempo, divertida, confiável e irresistível."}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p>A Smood Sweets é uma marca criada por três amigos europeus com a missão de oferecer doces saborosos, naturais e \"sem culpa\". Seu produto de lançamento, os Candy Dates, são tâmaras recheadas com combinações frutadas, com uma pegada nostálgica e ingredientes limpos. O desafio era criar uma loja virtual (e-commerce) na plataforma Shopify que não apenas vendesse o produto, mas que também transmitisse a essência leve, funcional e irresistível da marca.</p><p><strong>O Desafio: Traduzir Sabor em Pixels</strong></p><p>O principal desafio de design era transformar a atmosfera \"divertida, leve e acolhedora\" da identidade visual, fornecida pelo cliente, em uma experiência de compra digital coesa. Para um produto novo e de consumo por impulso, a experiência precisava resolver três pontos-chave:</p><ol><li><p><strong>Criar Apetite Visual:</strong>A interface deveria ser visualmente atraente o suficiente para fazer os visitantes desejarem provar um produto que nunca viram antes.</p></li><li><p><strong>Comunicar o Valor:</strong>O design precisava destacar de forma clara e rápida os diferenciais do produto (natural, sem culpa, ingredientes simples).</p></li><li><p><strong>Simplificar a Conversão:</strong>O processo de compra, do clique inicial ao checkout, deveria ser extremamente simples, rápido e intuitivo para minimizar qualquer atrito e maximizar as vendas.</p></li></ol><p>O projeto foi guiado por um processo iterativo para garantir que cada decisão de design estivesse alinhada com os objetivos da marca e as necessidades dos usuários.</p><p><strong>1. Imersão na Marca e Arquitetura</strong>O ponto de partida foi uma imersão nas referências visuais e na identidade enviadas pelo cliente. A partir daí, estruturamos a arquitetura da informação do site, definindo as páginas essenciais (Home, Página de Produto, Carrinho, Checkout) e o fluxo de navegação mais simples possível para o usuário.</p><p><strong>2. Prototipagem e Testes Iterativos</strong>Criamos protótipos interativos no Figma para simular a experiência de compra completa. Realizamos diversos<strong>testes de usabilidade</strong>com foco na jornada principal do cliente: encontrar um produto, entender seus ingredientes, adicioná-lo ao carrinho e finalizar a compra. O feedback coletado nesses testes foi crucial para refinar a disposição dos elementos, a clareza dos botões (CTAs) e a fluidez geral do processo.</p><p><strong>3. Design Visual (UI) e Refinamento</strong>Com a estrutura e o fluxo validados, aplicamos a identidade visual da marca na interface de alta fidelidade. O foco foi usar a paleta de cores, tipografia e imagens de alta qualidade para criar uma atmosfera convidativa e \"saborosa\". Cada detalhe, desde os ícones até a apresentação das informações nutricionais, foi desenhado para ser intuitivo, bonito e alinhado com a promessa de um doce natural e prazeroso.</p><p><strong>A Solução</strong></p><p>O resultado é uma loja virtual na plataforma Shopify que é tão agradável quanto os próprios Candy Dates. A solução final entregue foi:</p><ul><li><p><strong>Um e-commerce leve e funcional</strong>, com design responsivo e otimizado para compras via mobile.</p></li><li><p><strong>Páginas de produto claras e atraentes</strong>, que destacam os ingredientes naturais e incentivam a compra.</p></li><li><p><strong>Um fluxo de checkout simplificado</strong>, projetado para reduzir o abandono de carrinho e garantir uma experiência de compra positiva.</p></li></ul><p>A plataforma digital traduz com sucesso a essência da Smood Sweets, oferecendo uma experiência de compra que é, ao mesmo tempo, divertida, confiável e irresistível.</p>Candy Dates Candy Dates<p>UI/UX Design</p><p>Desenvolvimento</p><p>A Smood Sweets é uma marca criada por três amigos europeus com a missão de oferecer doces saborosos, naturais e \"sem culpa\". Seu produto de lançamento, os Candy Dates, são tâmaras recheadas com combinações frutadas, com uma pegada nostálgica e ingredientes limpos. O desafio era criar uma loja virtual (e-commerce) na plataforma Shopify que não apenas vendesse o produto, mas que também transmitisse a essência leve, funcional e irresistível da marca.</p><p><strong>O Desafio: Traduzir Sabor em Pixels</strong></p><p>O principal desafio de design era transformar a atmosfera \"divertida, leve e acolhedora\" da identidade visual, fornecida pelo cliente, em uma experiência de compra digital coesa. Para um produto novo e de consumo por impulso, a experiência precisava resolver três pontos-chave:</p><ol><li><p><strong>Criar Apetite Visual:</strong>A interface deveria ser visualmente atraente o suficiente para fazer os visitantes desejarem provar um produto que nunca viram antes.</p></li><li><p><strong>Comunicar o Valor:</strong>O design precisava destacar de forma clara e rápida os diferenciais do produto (natural, sem culpa, ingredientes simples).</p></li><li><p><strong>Simplificar a Conversão:</strong>O processo de compra, do clique inicial ao checkout, deveria ser extremamente simples, rápido e intuitivo para minimizar qualquer atrito e maximizar as vendas.</p></li></ol><p>O projeto foi guiado por um processo iterativo para garantir que cada decisão de design estivesse alinhada com os objetivos da marca e as necessidades dos usuários.</p><p><strong>1. Imersão na Marca e Arquitetura</strong>O ponto de partida foi uma imersão nas referências visuais e na identidade enviadas pelo cliente. A partir daí, estruturamos a arquitetura da informação do site, definindo as páginas essenciais (Home, Página de Produto, Carrinho, Checkout) e o fluxo de navegação mais simples possível para o usuário.</p><p><strong>2. Prototipagem e Testes Iterativos</strong>Criamos protótipos interativos no Figma para simular a experiência de compra completa. Realizamos diversos<strong>testes de usabilidade</strong>com foco na jornada principal do cliente: encontrar um produto, entender seus ingredientes, adicioná-lo ao carrinho e finalizar a compra. O feedback coletado nesses testes foi crucial para refinar a disposição dos elementos, a clareza dos botões (CTAs) e a fluidez geral do processo.</p><p><strong>3. Design Visual (UI) e Refinamento</strong>Com a estrutura e o fluxo validados, aplicamos a identidade visual da marca na interface de alta fidelidade. O foco foi usar a paleta de cores, tipografia e imagens de alta qualidade para criar uma atmosfera convidativa e \"saborosa\". Cada detalhe, desde os ícones até a apresentação das informações nutricionais, foi desenhado para ser intuitivo, bonito e alinhado com a promessa de um doce natural e prazeroso.</p><p><strong>A Solução</strong></p><p>O resultado é uma loja virtual na plataforma Shopify que é tão agradável quanto os próprios Candy Dates. A solução final entregue foi:</p><ul><li><p><strong>Um e-commerce leve e funcional</strong>, com design responsivo e otimizado para compras via mobile.</p></li><li><p><strong>Páginas de produto claras e atraentes</strong>, que destacam os ingredientes naturais e incentivam a compra.</p></li><li><p><strong>Um fluxo de checkout simplificado</strong>, projetado para reduzir o abandono de carrinho e garantir uma experiência de compra positiva.</p></li></ul><p>A plataforma digital traduz com sucesso a essência da Smood Sweets, oferecendo uma experiência de compra que é, ao mesmo tempo, divertida, confiável e irresistível.</p>Eric Clapton<p>Anterior</p><p>Anterior</p>Tri RS<p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/candy-dates/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/candy-dates/cover.jpg","external_url":"","featured_on_home":true,"home_order":5,"portfolio_order":5,"seo_title":"","seo_description":"","published_at":"2026-05-28T21:07:55.491007+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-05-28T21:07:55.491007+00:00"},{"id":"aad01bd8-5b4d-5eaf-a81e-62fe5574feea","legacy_id":"capri-housing","legacy_slug":"capri-housing","slug":"capri-housing","title":"Capri Housing","status":"published","categories":["UI/UX Design"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Capri Temporary Housing oferece acomodações de curta duração a preços acessíveis no Texas, Arizona e Califórnia, com um toque da hospitalidade italiana. É ideal para quem trabalha fora de casa, está entre duas casas ou simplesmente precisa de um lugar para ficar. Fomos encarregados de desenvolver uma&nbsp;interface de dashboard eficiente e fácil de usar&nbsp;para os colaboradores da Capri Housing. O objetivo principal era centralizar e otimizar a&nbsp;gestão de cadastros de clientes e corporações, o acompanhamento de chamados e a manipulação de formulários, essenciais para as operações diárias da empresa."}]},{"type":"paragraph","content":[{"type":"text","text":"A equipe da Capri Housing enfrentava um fluxo de trabalho operacional fragmentado, dependendo de sistemas descentralizados e planilhas para gerenciar clientes, chamados e contratos. Esse processo manual gerava ineficiência, risco de erros e dificultava o crescimento do negócio. O desafio era duplo: criar uma ferramenta interna poderosa para os colaboradores e, ao mesmo tempo, oferecer uma experiência digital fluida e moderna para os clientes."}]},{"type":"paragraph","content":[{"type":"text","text":"Adotamos uma metodologia de design centrada no usuário para garantir que a solução atendesse às necessidades reais tanto da equipe interna quanto dos clientes finais."}]},{"type":"paragraph","content":[{"type":"text","text":"1. Arquitetura e Wireframing (A Fundação) O desafio inicial foi criar, do zero, a arquitetura de informação e o fluxo de trabalho da dashboard. Começamos com esboços iniciais e avançamos para wireframes detalhados. Esta etapa foi fundamental para estruturar todo o sistema, mapear as jornadas dos colaboradores e garantir que as funcionalidades essenciais, como gestão de cadastros e acompanhamento de chamados, estivessem organizadas de forma lógica e intuitiva."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Design de Experiência Multidispositivo (A Estratégia) Identificamos dois contextos de uso distintos que exigiam soluções mobile diferentes:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Para os Clientes: A prioridade era uma experiência mobile fluida e de fácil acesso. Para isso, foi projetada a interface de um aplicativo dedicado (nativo) , focado nas funcionalidades essenciais para o hóspede."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Para os Colaboradores: A necessidade era de flexibilidade para acessar a plataforma de qualquer lugar. A solução foi criar uma versão web mobile responsiva da dashboard principal, garantindo que a gestão pudesse ser feita de forma otimizada em qualquer dispositivo."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"3. Design de Interface (UI) e Refinamento Iterativo Com os wireframes validados, avançamos para o design de alta fidelidade da interface. Aplicando a identidade visual da Capri, criamos um design limpo e funcional para a dashboard desktop. Durante este processo, realizamos diversos ajustes e melhorias na aparência e na interação, refinando os componentes para garantir a melhor usabilidade possível."}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto resultou em um ecossistema digital coeso, entregando três produtos de design interconectados:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A Dashboard Desktop: O hub central para as operações da Capri, permitindo que os funcionários gerenciem todo o negócio com eficiência e clareza."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A Versão Web Mobile para a Equipe: Garante que os colaboradores tenham acesso flexível e otimizado à plataforma em qualquer lugar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"O Aplicativo Mobile para Clientes: Oferece aos hóspedes uma experiência de autoatendimento moderna e conveniente."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Juntas, essas soluções otimizaram as operações internas, reduziram a carga de trabalho manual e elevaram o padrão do serviço oferecido pela Capri Housing."}]},{"type":"paragraph","content":[{"type":"text","text":"UI/UX Design"}]},{"type":"paragraph","content":[{"type":"text","text":"A Capri Temporary Housing oferece acomodações de curta duração a preços acessíveis no Texas, Arizona e Califórnia, com um toque da hospitalidade italiana. É ideal para quem trabalha fora de casa, está entre duas casas ou simplesmente precisa de um lugar para ficar. Fomos encarregados de desenvolver uma&nbsp;interface de dashboard eficiente e fácil de usar&nbsp;para os colaboradores da Capri Housing. O objetivo principal era centralizar e otimizar a&nbsp;gestão de cadastros de clientes e corporações, o acompanhamento de chamados e a manipulação de formulários, essenciais para as operações diárias da empresa."}]},{"type":"paragraph","content":[{"type":"text","text":"A equipe da Capri Housing enfrentava um fluxo de trabalho operacional fragmentado, dependendo de sistemas descentralizados e planilhas para gerenciar clientes, chamados e contratos. Esse processo manual gerava ineficiência, risco de erros e dificultava o crescimento do negócio. O desafio era duplo: criar uma ferramenta interna poderosa para os colaboradores e, ao mesmo tempo, oferecer uma experiência digital fluida e moderna para os clientes."}]},{"type":"paragraph","content":[{"type":"text","text":"Adotamos uma metodologia de design centrada no usuário para garantir que a solução atendesse às necessidades reais tanto da equipe interna quanto dos clientes finais."}]},{"type":"paragraph","content":[{"type":"text","text":"1. Arquitetura e Wireframing (A Fundação) O desafio inicial foi criar, do zero, a arquitetura de informação e o fluxo de trabalho da dashboard. Começamos com esboços iniciais e avançamos para wireframes detalhados. Esta etapa foi fundamental para estruturar todo o sistema, mapear as jornadas dos colaboradores e garantir que as funcionalidades essenciais, como gestão de cadastros e acompanhamento de chamados, estivessem organizadas de forma lógica e intuitiva."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Design de Experiência Multidispositivo (A Estratégia) Identificamos dois contextos de uso distintos que exigiam soluções mobile diferentes:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Para os Clientes: A prioridade era uma experiência mobile fluida e de fácil acesso. Para isso, foi projetada a interface de um aplicativo dedicado (nativo) , focado nas funcionalidades essenciais para o hóspede."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Para os Colaboradores: A necessidade era de flexibilidade para acessar a plataforma de qualquer lugar. A solução foi criar uma versão web mobile responsiva da dashboard principal, garantindo que a gestão pudesse ser feita de forma otimizada em qualquer dispositivo."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"3. Design de Interface (UI) e Refinamento Iterativo Com os wireframes validados, avançamos para o design de alta fidelidade da interface. Aplicando a identidade visual da Capri, criamos um design limpo e funcional para a dashboard desktop. Durante este processo, realizamos diversos ajustes e melhorias na aparência e na interação, refinando os componentes para garantir a melhor usabilidade possível."}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto resultou em um ecossistema digital coeso, entregando três produtos de design interconectados:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A Dashboard Desktop: O hub central para as operações da Capri, permitindo que os funcionários gerenciem todo o negócio com eficiência e clareza."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A Versão Web Mobile para a Equipe: Garante que os colaboradores tenham acesso flexível e otimizado à plataforma em qualquer lugar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"O Aplicativo Mobile para Clientes: Oferece aos hóspedes uma experiência de autoatendimento moderna e conveniente."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Juntas, essas soluções otimizaram as operações internas, reduziram a carga de trabalho manual e elevaram o padrão do serviço oferecido pela Capri Housing."}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p>A Capri Temporary Housing oferece acomodações de curta duração a preços acessíveis no Texas, Arizona e Califórnia, com um toque da hospitalidade italiana. É ideal para quem trabalha fora de casa, está entre duas casas ou simplesmente precisa de um lugar para ficar.<br><br>Fomos encarregados de desenvolver uma&nbsp;interface de dashboard eficiente e fácil de usar&nbsp;para os colaboradores da Capri Housing. O objetivo principal era centralizar e otimizar a&nbsp;gestão de cadastros de clientes e corporações, o acompanhamento de chamados e a manipulação de formulários, essenciais para as operações diárias da empresa.</p><p>A equipe da Capri Housing enfrentava um fluxo de trabalho operacional fragmentado, dependendo de sistemas descentralizados e planilhas para gerenciar clientes, chamados e contratos. Esse processo manual gerava ineficiência, risco de erros e dificultava o crescimento do negócio. O desafio era duplo: criar uma ferramenta interna poderosa para os colaboradores e, ao mesmo tempo, oferecer uma experiência digital fluida e moderna para os clientes.</p><p>Adotamos uma metodologia de design centrada no usuário para garantir que a solução atendesse às necessidades reais tanto da equipe interna quanto dos clientes finais.</p><p><strong>1. Arquitetura e Wireframing (A Fundação)</strong>O desafio inicial foi criar, do zero, a arquitetura de informação e o fluxo de trabalho da dashboard. Começamos com esboços iniciais e avançamos para wireframes detalhados. Esta etapa foi fundamental para estruturar todo o sistema, mapear as jornadas dos colaboradores e garantir que as funcionalidades essenciais, como gestão de cadastros e acompanhamento de chamados, estivessem organizadas de forma lógica e intuitiva.</p><p><strong>2. Design de Experiência Multidispositivo (A Estratégia)</strong>Identificamos dois contextos de uso distintos que exigiam soluções mobile diferentes:</p><ul><li><p><strong>Para os Clientes:</strong>A prioridade era uma experiência mobile fluida e de fácil acesso. Para isso, foi projetada a interface de um<strong>aplicativo dedicado (nativo)</strong>, focado nas funcionalidades essenciais para o hóspede.</p></li><li><p><strong>Para os Colaboradores:</strong>A necessidade era de flexibilidade para acessar a plataforma de qualquer lugar. A solução foi criar uma<strong>versão web mobile responsiva</strong>da dashboard principal, garantindo que a gestão pudesse ser feita de forma otimizada em qualquer dispositivo.</p></li></ul><p><strong>3. Design de Interface (UI) e Refinamento Iterativo</strong>Com os wireframes validados, avançamos para o design de alta fidelidade da interface. Aplicando a identidade visual da Capri, criamos um design limpo e funcional para a dashboard desktop. Durante este processo, realizamos diversos ajustes e melhorias na aparência e na interação, refinando os componentes para garantir a melhor usabilidade possível.</p><p>O projeto resultou em um ecossistema digital coeso, entregando três produtos de design interconectados:</p><ol><li><p><strong>A Dashboard Desktop:</strong>O hub central para as operações da Capri, permitindo que os funcionários gerenciem todo o negócio com eficiência e clareza.</p></li><li><p><strong>A Versão Web Mobile para a Equipe:</strong>Garante que os colaboradores tenham acesso flexível e otimizado à plataforma em qualquer lugar.</p></li><li><p><strong>O Aplicativo Mobile para Clientes:</strong>Oferece aos hóspedes uma experiência de autoatendimento moderna e conveniente.</p></li></ol><p>Juntas, essas soluções otimizaram as operações internas, reduziram a carga de trabalho manual e elevaram o padrão do serviço oferecido pela Capri Housing.</p>Capri Housing Capri Housing<p>UI/UX Design</p><p>A Capri Temporary Housing oferece acomodações de curta duração a preços acessíveis no Texas, Arizona e Califórnia, com um toque da hospitalidade italiana. É ideal para quem trabalha fora de casa, está entre duas casas ou simplesmente precisa de um lugar para ficar.<br><br>Fomos encarregados de desenvolver uma&nbsp;interface de dashboard eficiente e fácil de usar&nbsp;para os colaboradores da Capri Housing. O objetivo principal era centralizar e otimizar a&nbsp;gestão de cadastros de clientes e corporações, o acompanhamento de chamados e a manipulação de formulários, essenciais para as operações diárias da empresa.</p><p>A equipe da Capri Housing enfrentava um fluxo de trabalho operacional fragmentado, dependendo de sistemas descentralizados e planilhas para gerenciar clientes, chamados e contratos. Esse processo manual gerava ineficiência, risco de erros e dificultava o crescimento do negócio. O desafio era duplo: criar uma ferramenta interna poderosa para os colaboradores e, ao mesmo tempo, oferecer uma experiência digital fluida e moderna para os clientes.</p><p>Adotamos uma metodologia de design centrada no usuário para garantir que a solução atendesse às necessidades reais tanto da equipe interna quanto dos clientes finais.</p><p><strong>1. Arquitetura e Wireframing (A Fundação)</strong>O desafio inicial foi criar, do zero, a arquitetura de informação e o fluxo de trabalho da dashboard. Começamos com esboços iniciais e avançamos para wireframes detalhados. Esta etapa foi fundamental para estruturar todo o sistema, mapear as jornadas dos colaboradores e garantir que as funcionalidades essenciais, como gestão de cadastros e acompanhamento de chamados, estivessem organizadas de forma lógica e intuitiva.</p><p><strong>2. Design de Experiência Multidispositivo (A Estratégia)</strong>Identificamos dois contextos de uso distintos que exigiam soluções mobile diferentes:</p><ul><li><p><strong>Para os Clientes:</strong>A prioridade era uma experiência mobile fluida e de fácil acesso. Para isso, foi projetada a interface de um<strong>aplicativo dedicado (nativo)</strong>, focado nas funcionalidades essenciais para o hóspede.</p></li><li><p><strong>Para os Colaboradores:</strong>A necessidade era de flexibilidade para acessar a plataforma de qualquer lugar. A solução foi criar uma<strong>versão web mobile responsiva</strong>da dashboard principal, garantindo que a gestão pudesse ser feita de forma otimizada em qualquer dispositivo.</p></li></ul><p><strong>3. Design de Interface (UI) e Refinamento Iterativo</strong>Com os wireframes validados, avançamos para o design de alta fidelidade da interface. Aplicando a identidade visual da Capri, criamos um design limpo e funcional para a dashboard desktop. Durante este processo, realizamos diversos ajustes e melhorias na aparência e na interação, refinando os componentes para garantir a melhor usabilidade possível.</p><p>O projeto resultou em um ecossistema digital coeso, entregando três produtos de design interconectados:</p><ol><li><p><strong>A Dashboard Desktop:</strong>O hub central para as operações da Capri, permitindo que os funcionários gerenciem todo o negócio com eficiência e clareza.</p></li><li><p><strong>A Versão Web Mobile para a Equipe:</strong>Garante que os colaboradores tenham acesso flexível e otimizado à plataforma em qualquer lugar.</p></li><li><p><strong>O Aplicativo Mobile para Clientes:</strong>Oferece aos hóspedes uma experiência de autoatendimento moderna e conveniente.</p></li></ol><p>Juntas, essas soluções otimizaram as operações internas, reduziram a carga de trabalho manual e elevaram o padrão do serviço oferecido pela Capri Housing.</p>Blenduca<p>Anterior</p><p>Anterior</p>BU1LD<p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/capri-housing/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/capri-housing/cover.jpg","external_url":"","featured_on_home":false,"home_order":999,"portfolio_order":26,"seo_title":"","seo_description":"","published_at":"2026-05-28T21:07:55.491007+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-05-28T21:07:55.491007+00:00"},{"id":"3664e7d6-c9e4-5d09-8b6c-0da96faa136d","legacy_id":"click-impresso","legacy_slug":"click-impresso","slug":"click-impresso","title":"Click Impresso","status":"published","categories":["Branding","Editorial"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Click Impresso é uma gráfica expressa com 16 lojas no Rio Grande do Sul, fazendo parte do Grupo Impresul, uma referência no setor gráfico há mais de 56 anos. Reconhecida como a gráfica mais premiada do Sul do Brasil, a empresa se baseia em um compromisso com a qualidade de impressão, prazos rápidos e atendimento personalizado."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O desafio foi duplo:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No Digital: Traduzir o vasto e tátil portfólio de produtos da gráfica para o ambiente dinâmico das redes sociais, de uma forma que fosse visualmente atrativa e gerasse desejo."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No Corporativo: Unificar e profissionalizar a identidade visual dos materiais internos e de contato da equipe."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução de Design"}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto foi dividido em duas frentes estratégicas de comunicação para atender a esses desafios:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Design para Redes Sociais Foi desenvolvida uma linha editorial visual para as redes sociais com o objetivo de promover a diversidade de produtos e serviços da gráfica. Para tangibilizar as possibilidades de impressão, foram criados posts estáticos e carrosséis que utilizavam mockups de alta qualidade como exemplos."}]},{"type":"paragraph","content":[{"type":"text","text":"Esses mockups demonstravam a aplicação em uma ampla gama de produtos — como camisetas, copos, adesivos, quadros, almofadas, buttons e cadernos — sempre acompanhados por chamadas de ação (CTAs) para atrair o público."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Kit de Marketing Corporativo Para garantir a consistência e o profissionalismo da marca nos pontos de contato da equipe, foi criado um kit de marketing essencial. Este conjunto de materiais incluiu o design de cartões de visita para os funcionários, crachás de identificação, camisetas de uniforme e um flyer informativo com os serviços da empresa."}]},{"type":"paragraph","content":[{"type":"text","text":"Branding"}]},{"type":"paragraph","content":[{"type":"text","text":"Editorial"}]},{"type":"paragraph","content":[{"type":"text","text":"A Click Impresso é uma gráfica expressa com 16 lojas no Rio Grande do Sul, fazendo parte do Grupo Impresul, uma referência no setor gráfico há mais de 56 anos. Reconhecida como a gráfica mais premiada do Sul do Brasil, a empresa se baseia em um compromisso com a qualidade de impressão, prazos rápidos e atendimento personalizado."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio"}]},{"type":"paragraph","content":[{"type":"text","text":"O desafio foi duplo:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No Digital: Traduzir o vasto e tátil portfólio de produtos da gráfica para o ambiente dinâmico das redes sociais, de uma forma que fosse visualmente atrativa e gerasse desejo."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No Corporativo: Unificar e profissionalizar a identidade visual dos materiais internos e de contato da equipe."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução de Design"}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto foi dividido em duas frentes estratégicas de comunicação para atender a esses desafios:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Design para Redes Sociais Foi desenvolvida uma linha editorial visual para as redes sociais com o objetivo de promover a diversidade de produtos e serviços da gráfica. Para tangibilizar as possibilidades de impressão, foram criados posts estáticos e carrosséis que utilizavam mockups de alta qualidade como exemplos."}]},{"type":"paragraph","content":[{"type":"text","text":"Esses mockups demonstravam a aplicação em uma ampla gama de produtos — como camisetas, copos, adesivos, quadros, almofadas, buttons e cadernos — sempre acompanhados por chamadas de ação (CTAs) para atrair o público."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Kit de Marketing Corporativo Para garantir a consistência e o profissionalismo da marca nos pontos de contato da equipe, foi criado um kit de marketing essencial. Este conjunto de materiais incluiu o design de cartões de visita para os funcionários, crachás de identificação, camisetas de uniforme e um flyer informativo com os serviços da empresa."}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p>A Click Impresso é uma gráfica expressa com 16 lojas no Rio Grande do Sul, fazendo parte do Grupo Impresul, uma referência no setor gráfico há mais de 56 anos. Reconhecida como a gráfica mais premiada do Sul do Brasil, a empresa se baseia em um compromisso com a qualidade de impressão, prazos rápidos e atendimento personalizado.</p><p><strong>O Desafio</strong></p><p>O desafio foi duplo:</p><ol><li><p><strong>No Digital:</strong>Traduzir o vasto e tátil portfólio de produtos da gráfica para o ambiente dinâmico das redes sociais, de uma forma que fosse visualmente atrativa e gerasse desejo.</p></li><li><p><strong>No Corporativo:</strong>Unificar e profissionalizar a identidade visual dos materiais internos e de contato da equipe.</p></li></ol><p><strong>A Solução de Design</strong></p><p>O projeto foi dividido em duas frentes estratégicas de comunicação para atender a esses desafios:</p><p><strong>1. Design para Redes Sociais</strong><br>Foi desenvolvida uma linha editorial visual para as redes sociais com o objetivo de promover a diversidade de produtos e serviços da gráfica. Para tangibilizar as possibilidades de impressão, foram criados posts estáticos e carrosséis que utilizavam<em>mockups</em>de alta qualidade como exemplos.</p><p>Esses<em>mockups</em>demonstravam a aplicação em uma ampla gama de produtos — como camisetas, copos, adesivos, quadros, almofadas, buttons e cadernos — sempre acompanhados por chamadas de ação (CTAs) para atrair o público.</p><p><strong>2. Kit de Marketing Corporativo</strong><br>Para garantir a consistência e o profissionalismo da marca nos pontos de contato da equipe, foi criado um kit de marketing essencial. Este conjunto de materiais incluiu o design de cartões de visita para os funcionários, crachás de identificação, camisetas de uniforme e um flyer informativo com os serviços da empresa.</p>Click Impresso Click Impresso<p>Branding</p><p>Editorial</p><p>A Click Impresso é uma gráfica expressa com 16 lojas no Rio Grande do Sul, fazendo parte do Grupo Impresul, uma referência no setor gráfico há mais de 56 anos. Reconhecida como a gráfica mais premiada do Sul do Brasil, a empresa se baseia em um compromisso com a qualidade de impressão, prazos rápidos e atendimento personalizado.</p><p><strong>O Desafio</strong></p><p>O desafio foi duplo:</p><ol><li><p><strong>No Digital:</strong>Traduzir o vasto e tátil portfólio de produtos da gráfica para o ambiente dinâmico das redes sociais, de uma forma que fosse visualmente atrativa e gerasse desejo.</p></li><li><p><strong>No Corporativo:</strong>Unificar e profissionalizar a identidade visual dos materiais internos e de contato da equipe.</p></li></ol><p><strong>A Solução de Design</strong></p><p>O projeto foi dividido em duas frentes estratégicas de comunicação para atender a esses desafios:</p><p><strong>1. Design para Redes Sociais</strong><br>Foi desenvolvida uma linha editorial visual para as redes sociais com o objetivo de promover a diversidade de produtos e serviços da gráfica. Para tangibilizar as possibilidades de impressão, foram criados posts estáticos e carrosséis que utilizavam<em>mockups</em>de alta qualidade como exemplos.</p><p>Esses<em>mockups</em>demonstravam a aplicação em uma ampla gama de produtos — como camisetas, copos, adesivos, quadros, almofadas, buttons e cadernos — sempre acompanhados por chamadas de ação (CTAs) para atrair o público.</p><p><strong>2. Kit de Marketing Corporativo</strong><br>Para garantir a consistência e o profissionalismo da marca nos pontos de contato da equipe, foi criado um kit de marketing essencial. Este conjunto de materiais incluiu o design de cartões de visita para os funcionários, crachás de identificação, camisetas de uniforme e um flyer informativo com os serviços da empresa.</p>Calendário Impresul 2023<p>Anterior</p><p>Anterior</p>Calendário Impresul 2024<p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/click-impresso/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/click-impresso/cover.jpg","external_url":"","featured_on_home":false,"home_order":999,"portfolio_order":14,"seo_title":"","seo_description":"","published_at":"2026-05-28T20:21:07.399076+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-05-28T20:21:07.399076+00:00"},{"id":"4fe59d61-6718-55f6-b4e2-0d56ff40a1a3","legacy_id":"dark-star","legacy_slug":"dark-star","slug":"dark-star","title":"Dark Star","status":"published","categories":["UI/UX Design","Desenvolvimento","Branding","Editorial"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dark Star é uma consultoria de arte sediada em Miami, especializada na curadoria, aquisição e posicionamento de obras de artistas contemporâneos, de meio de carreira e do pós-guerra. A empresa atua como uma ponte estratégica nos bastidores do mundo da arte, conectando artistas e colecionadores."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio Conceitual"}]},{"type":"paragraph","content":[{"type":"text","text":"Como criar uma identidade visual para uma marca cujo maior valor está na sua discrição e influência sutil? O desafio era traduzir visualmente o conceito de uma \"estrela sombria\" (dark star) — uma entidade invisível, mas fundamental, cuja presença é percebida apenas por sua influência gravitacional. A marca não deveria ser o foco, mas sim o \"palco\" elegante e neutro que permite que as obras de arte, os artistas e os colecionadores brilhem."}]},{"type":"paragraph","content":[{"type":"text","text":"O Processo Criativo e a Construção do Universo Visual"}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto foi desenvolvido a partir da exploração da metáfora central: assim como uma estrela escura organiza sistemas solares, um consultor de arte organiza coleções e espaços, criando ordem e harmonia. Cada elemento da identidade foi criado para reforçar essa ideia."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tipografia:&nbsp;A família tipográfica escolhida foi a&nbsp;Afacad, uma fonte sans-serif com proporções arquitetônicas.&nbsp;Suas terminações nítidas e formas sóbrias conferem um visual elegante e minimalista, alinhado à sofisticação do mercado de arte."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Logomark:&nbsp;O ícone da marca consiste em uma grade de quatro círculos que, através do&nbsp;Princípio de Gestalt, formam uma estrela no espaço negativo central.&nbsp;Esta \"estrela escura\" só é perceptível por causa dos elementos que a orbitam, uma representação perfeita do papel influente e discreto do consultor de arte."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paleta de Cores:&nbsp;Foi definida uma paleta monocromática, dominada por tons de preto fosco e cinza.&nbsp;A escolha estratégica reflete a natureza discreta da marca e serve a um propósito funcional: criar uma base neutra que permite que as cores vibrantes das obras de arte se destaquem, tornando-se o ponto focal em qualquer composição."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução: Um Ecossistema Visual Completo"}]},{"type":"paragraph","content":[{"type":"text","text":"O resultado é um manual de identidade visual abrangente que estabelece um ecossistema coeso e flexível para a marca Dark Star. A solução de design vai além do logo, definindo diretrizes claras para todos os pontos de contato da marca."}]},{"type":"paragraph","content":[{"type":"text","text":"Os elementos-chave da identidade incluem:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Construção e Uso do Logo:&nbsp;Regras de proporção, área de segurança e escala mínima para garantir a integridade e legibilidade em todas as aplicações."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Padrões e Texturas:&nbsp;O sistema inclui padrões gráficos derivados do logomark e texturas abstratas com ondulações, uma referência visual às \"ondas gravitacionais\" que unem os elementos no universo da marca."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Diretrizes de Aplicação:&nbsp;Regras claras para o uso da marca em fundos neutros, coloridos e em contextos 3D, sempre priorizando o contraste adequado e a sensação tátil de \"preto fosco\" que define a marca."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Esta identidade visual não apenas dá uma cara à Dark Star, mas também lhe fornece uma filosofia visual que é, ao mesmo tempo, invisível e fundamental, assim como o seu trabalho."}]},{"type":"paragraph","content":[{"type":"text","text":"UI/UX Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Desenvolvimento"}]},{"type":"paragraph","content":[{"type":"text","text":"Branding"}]},{"type":"paragraph","content":[{"type":"text","text":"Editorial"}]},{"type":"paragraph","content":[{"type":"text","text":"Acessar website"}]},{"type":"paragraph","content":[{"type":"text","text":"Acessar website"}]},{"type":"paragraph","content":[{"type":"text","text":"Acessar website"}]},{"type":"paragraph","content":[{"type":"text","text":"Dark Star é uma consultoria de arte sediada em Miami, especializada na curadoria, aquisição e posicionamento de obras de artistas contemporâneos, de meio de carreira e do pós-guerra. A empresa atua como uma ponte estratégica nos bastidores do mundo da arte, conectando artistas e colecionadores."}]},{"type":"paragraph","content":[{"type":"text","text":"O Desafio Conceitual"}]},{"type":"paragraph","content":[{"type":"text","text":"Como criar uma identidade visual para uma marca cujo maior valor está na sua discrição e influência sutil? O desafio era traduzir visualmente o conceito de uma \"estrela sombria\" (dark star) — uma entidade invisível, mas fundamental, cuja presença é percebida apenas por sua influência gravitacional. A marca não deveria ser o foco, mas sim o \"palco\" elegante e neutro que permite que as obras de arte, os artistas e os colecionadores brilhem."}]},{"type":"paragraph","content":[{"type":"text","text":"O Processo Criativo e a Construção do Universo Visual"}]},{"type":"paragraph","content":[{"type":"text","text":"O projeto foi desenvolvido a partir da exploração da metáfora central: assim como uma estrela escura organiza sistemas solares, um consultor de arte organiza coleções e espaços, criando ordem e harmonia. Cada elemento da identidade foi criado para reforçar essa ideia."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tipografia:&nbsp;A família tipográfica escolhida foi a&nbsp;Afacad, uma fonte sans-serif com proporções arquitetônicas.&nbsp;Suas terminações nítidas e formas sóbrias conferem um visual elegante e minimalista, alinhado à sofisticação do mercado de arte."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Logomark:&nbsp;O ícone da marca consiste em uma grade de quatro círculos que, através do&nbsp;Princípio de Gestalt, formam uma estrela no espaço negativo central.&nbsp;Esta \"estrela escura\" só é perceptível por causa dos elementos que a orbitam, uma representação perfeita do papel influente e discreto do consultor de arte."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paleta de Cores:&nbsp;Foi definida uma paleta monocromática, dominada por tons de preto fosco e cinza.&nbsp;A escolha estratégica reflete a natureza discreta da marca e serve a um propósito funcional: criar uma base neutra que permite que as cores vibrantes das obras de arte se destaquem, tornando-se o ponto focal em qualquer composição."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A Solução: Um Ecossistema Visual Completo"}]},{"type":"paragraph","content":[{"type":"text","text":"O resultado é um manual de identidade visual abrangente que estabelece um ecossistema coeso e flexível para a marca Dark Star. A solução de design vai além do logo, definindo diretrizes claras para todos os pontos de contato da marca."}]},{"type":"paragraph","content":[{"type":"text","text":"Os elementos-chave da identidade incluem:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Construção e Uso do Logo:&nbsp;Regras de proporção, área de segurança e escala mínima para garantir a integridade e legibilidade em todas as aplicações."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Padrões e Texturas:&nbsp;O sistema inclui padrões gráficos derivados do logomark e texturas abstratas com ondulações, uma referência visual às \"ondas gravitacionais\" que unem os elementos no universo da marca."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Diretrizes de Aplicação:&nbsp;Regras claras para o uso da marca em fundos neutros, coloridos e em contextos 3D, sempre priorizando o contraste adequado e a sensação tátil de \"preto fosco\" que define a marca."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Esta identidade visual não apenas dá uma cara à Dark Star, mas também lhe fornece uma filosofia visual que é, ao mesmo tempo, invisível e fundamental, assim como o seu trabalho."}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Anterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]},{"type":"paragraph","content":[{"type":"text","text":"Próximo"}]}]},"content_html":"<p>Dark Star é uma consultoria de arte sediada em Miami, especializada na curadoria, aquisição e posicionamento de obras de artistas contemporâneos, de meio de carreira e do pós-guerra. A empresa atua como uma ponte estratégica nos bastidores do mundo da arte, conectando artistas e colecionadores.</p><p><strong>O Desafio Conceitual</strong></p><p>Como criar uma identidade visual para uma marca cujo maior valor está na sua discrição e influência sutil? O desafio era traduzir visualmente o conceito de uma \"estrela sombria\" (dark star) — uma entidade invisível, mas fundamental, cuja presença é percebida apenas por sua influência gravitacional. A marca não deveria ser o foco, mas sim o \"palco\" elegante e neutro que permite que as obras de arte, os artistas e os colecionadores brilhem.</p><p><strong>O Processo Criativo e a Construção do Universo Visual</strong></p><p>O projeto foi desenvolvido a partir da exploração da metáfora central: assim como uma estrela escura organiza sistemas solares, um consultor de arte organiza coleções e espaços, criando ordem e harmonia. Cada elemento da identidade foi criado para reforçar essa ideia.</p><ul><li><p>Tipografia:&nbsp;A família tipográfica escolhida foi a&nbsp;Afacad, uma fonte sans-serif com proporções arquitetônicas.&nbsp;Suas terminações nítidas e formas sóbrias conferem um visual elegante e minimalista, alinhado à sofisticação do mercado de arte.</p></li><li><p>Logomark:&nbsp;O ícone da marca consiste em uma grade de quatro círculos que, através do&nbsp;Princípio de Gestalt, formam uma estrela no espaço negativo central.&nbsp;Esta \"estrela escura\" só é perceptível por causa dos elementos que a orbitam, uma representação perfeita do papel influente e discreto do consultor de arte.</p></li><li><p>Paleta de Cores:&nbsp;Foi definida uma paleta monocromática, dominada por tons de preto fosco e cinza.&nbsp;A escolha estratégica reflete a natureza discreta da marca e serve a um propósito funcional: criar uma base neutra que permite que as cores vibrantes das obras de arte se destaquem, tornando-se o ponto focal em qualquer composição.</p></li></ul><p><strong>A Solução: Um Ecossistema Visual Completo</strong></p><p>O resultado é um manual de identidade visual abrangente que estabelece um ecossistema coeso e flexível para a marca Dark Star. A solução de design vai além do logo, definindo diretrizes claras para todos os pontos de contato da marca.</p><p>Os elementos-chave da identidade incluem:</p><ul><li><p>Construção e Uso do Logo:&nbsp;Regras de proporção, área de segurança e escala mínima para garantir a integridade e legibilidade em todas as aplicações.</p></li><li><p>Padrões e Texturas:&nbsp;O sistema inclui padrões gráficos derivados do logomark e texturas abstratas com ondulações, uma referência visual às \"ondas gravitacionais\" que unem os elementos no universo da marca.</p></li><li><p>Diretrizes de Aplicação:&nbsp;Regras claras para o uso da marca em fundos neutros, coloridos e em contextos 3D, sempre priorizando o contraste adequado e a sensação tátil de \"preto fosco\" que define a marca.</p></li></ul><p>Esta identidade visual não apenas dá uma cara à Dark Star, mas também lhe fornece uma filosofia visual que é, ao mesmo tempo, invisível e fundamental, assim como o seu trabalho.</p>Dark Star Dark Star<p>UI/UX Design</p><p>Desenvolvimento</p><p>Branding</p><p>Editorial</p><p>Acessar website</p><p>Acessar website</p><p>Acessar website</p><p>Dark Star é uma consultoria de arte sediada em Miami, especializada na curadoria, aquisição e posicionamento de obras de artistas contemporâneos, de meio de carreira e do pós-guerra. A empresa atua como uma ponte estratégica nos bastidores do mundo da arte, conectando artistas e colecionadores.</p><p><strong>O Desafio Conceitual</strong></p><p>Como criar uma identidade visual para uma marca cujo maior valor está na sua discrição e influência sutil? O desafio era traduzir visualmente o conceito de uma \"estrela sombria\" (dark star) — uma entidade invisível, mas fundamental, cuja presença é percebida apenas por sua influência gravitacional. A marca não deveria ser o foco, mas sim o \"palco\" elegante e neutro que permite que as obras de arte, os artistas e os colecionadores brilhem.</p><p><strong>O Processo Criativo e a Construção do Universo Visual</strong></p><p>O projeto foi desenvolvido a partir da exploração da metáfora central: assim como uma estrela escura organiza sistemas solares, um consultor de arte organiza coleções e espaços, criando ordem e harmonia. Cada elemento da identidade foi criado para reforçar essa ideia.</p><ul><li><p>Tipografia:&nbsp;A família tipográfica escolhida foi a&nbsp;Afacad, uma fonte sans-serif com proporções arquitetônicas.&nbsp;Suas terminações nítidas e formas sóbrias conferem um visual elegante e minimalista, alinhado à sofisticação do mercado de arte.</p></li><li><p>Logomark:&nbsp;O ícone da marca consiste em uma grade de quatro círculos que, através do&nbsp;Princípio de Gestalt, formam uma estrela no espaço negativo central.&nbsp;Esta \"estrela escura\" só é perceptível por causa dos elementos que a orbitam, uma representação perfeita do papel influente e discreto do consultor de arte.</p></li><li><p>Paleta de Cores:&nbsp;Foi definida uma paleta monocromática, dominada por tons de preto fosco e cinza.&nbsp;A escolha estratégica reflete a natureza discreta da marca e serve a um propósito funcional: criar uma base neutra que permite que as cores vibrantes das obras de arte se destaquem, tornando-se o ponto focal em qualquer composição.</p></li></ul><p><strong>A Solução: Um Ecossistema Visual Completo</strong></p><p>O resultado é um manual de identidade visual abrangente que estabelece um ecossistema coeso e flexível para a marca Dark Star. A solução de design vai além do logo, definindo diretrizes claras para todos os pontos de contato da marca.</p><p>Os elementos-chave da identidade incluem:</p><ul><li><p>Construção e Uso do Logo:&nbsp;Regras de proporção, área de segurança e escala mínima para garantir a integridade e legibilidade em todas as aplicações.</p></li><li><p>Padrões e Texturas:&nbsp;O sistema inclui padrões gráficos derivados do logomark e texturas abstratas com ondulações, uma referência visual às \"ondas gravitacionais\" que unem os elementos no universo da marca.</p></li><li><p>Diretrizes de Aplicação:&nbsp;Regras claras para o uso da marca em fundos neutros, coloridos e em contextos 3D, sempre priorizando o contraste adequado e a sensação tátil de \"preto fosco\" que define a marca.</p></li></ul><p>Esta identidade visual não apenas dá uma cara à Dark Star, mas também lhe fornece uma filosofia visual que é, ao mesmo tempo, invisível e fundamental, assim como o seu trabalho.</p>Restiview<p>Anterior</p><p>Anterior</p><p>Próximo</p><p>Próximo</p>","cover_url":"https://yzivkrotylwyglavtnho.supabase.co/storage/v1/object/public/case-images/cases/dark-star/cover.jpg","cover_storage_bucket":"case-images","cover_storage_path":"cases/dark-star/cover.jpg","external_url":"https://quiet-access-957752.framer.app/","featured_on_home":false,"home_order":999,"portfolio_order":31,"seo_title":"","seo_description":"","published_at":"2026-06-01T14:19:37.302014+00:00","created_by":null,"updated_by":null,"version":1,"created_at":"2026-05-15T23:33:58.021307+00:00","updated_at":"2026-06-01T14:19:37.302014+00:00"},{"id":"378bfe66-fe26-5b55-90d4-8af8542cc5d7","legacy_id":"definna","legacy_slug":"definna","slug":"definna","title":"Definna","status":"published","categories":["UI/UX Design","Desenvolvimento"],"excerpt":"","content_json":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Definna é uma plataforma SaaS (Software as a Service) projetada para empresas construírem, integrarem e monitorarem uma força de 