create temp table _portfolio_migration_excluded on commit drop as
select jsonb_array_elements_text($portfolio_migration_json$["novo-case-1779977160261","novo-case-1780068948570","novo-case-1780074762889","novo-case-1780960017640"]$portfolio_migration_json$::jsonb) as slug;

do $$
begin
  if (select count(*) from _portfolio_migration_cases) <> 36 then
    raise exception 'Expected 36 migration cases.';
  end if;
  if (select count(*) from _portfolio_migration_excluded) <> 4 then
    raise exception 'Expected 4 excluded cases.';
  end if;
  if exists (select 1 from _portfolio_migration_cases c join _portfolio_migration_excluded e on e.slug = c.slug) then
    raise exception 'Excluded novo-case record is present in migration cases.';
  end if;
  if (select count(*) from public.cases) <> 40 then
    raise exception 'public.cases count changed before apply.';
  end if;
  if exists (select 1 from public.portfolio_cases pc where not exists (select 1 from _portfolio_migration_cases mc where mc.id = pc.id)) then
    raise exception 'portfolio_cases contains rows outside this migration.';
  end if;
  if exists (select 1 from public.portfolio_case_media pm where not exists (select 1 from _portfolio_migration_media mm where mm.id = pm.id)) then
    raise exception 'portfolio_case_media contains rows outside this migration.';
  end if;
  if exists (select 1 from public.portfolio_case_slug_history) then
    raise exception 'portfolio_case_slug_history is not empty.';
  end if;
  if exists (
    select 1
    from public.portfolio_cases pc
    join _portfolio_migration_cases mc on mc.id = pc.id
    where pc.legacy_id is distinct from mc.legacy_id
      or pc.legacy_slug is distinct from mc.legacy_slug
      or pc.slug is distinct from mc.slug
      or pc.title is distinct from mc.title
      or pc.status is distinct from mc.status
      or pc.categories is distinct from mc.categories
      or pc.excerpt is distinct from mc.excerpt
      or pc.content_json is distinct from mc.content_json
      or pc.content_html is distinct from mc.content_html
      or pc.cover_url is distinct from mc.cover_url
      or pc.cover_storage_bucket is distinct from mc.cover_storage_bucket
      or pc.cover_storage_path is distinct from mc.cover_storage_path
      or pc.external_url is distinct from mc.external_url
      or pc.featured_on_home is distinct from mc.featured_on_home
      or pc.home_order is distinct from mc.home_order
      or pc.portfolio_order is distinct from mc.portfolio_order
      or pc.seo_title is distinct from mc.seo_title
      or pc.seo_description is distinct from mc.seo_description
      or pc.published_at is distinct from mc.published_at
      or pc.created_by is distinct from mc.created_by
      or pc.updated_by is distinct from mc.updated_by
      or pc.version is distinct from mc.version
      or pc.created_at is distinct from mc.created_at
      or pc.updated_at is distinct from mc.updated_at
  ) then
    raise exception 'Existing portfolio_cases row conflicts with deterministic migration payload.';
  end if;
  if exists (
    select 1
    from public.portfolio_case_media pm
    join _portfolio_migration_media mm on mm.id = pm.id
    where pm.case_id is distinct from mm.case_id
      or pm.source_url is distinct from mm.source_url
      or pm.storage_bucket is distinct from mm.storage_bucket
      or pm.storage_path is distinct from mm.storage_path
      or pm.media_type is distinct from mm.media_type
      or pm.alt_text is distinct from mm.alt_text
      or pm.caption is distinct from mm.caption
      or pm.width is distinct from mm.width
      or pm.height is distinct from mm.height
      or pm.sort_order is distinct from mm.sort_order
  ) then
    raise exception 'Existing portfolio_case_media row conflicts with deterministic migration payload.';
  end if;
end $$;

insert into public.portfolio_cases (
  id, legacy_id, legacy_slug, slug, title, status, categories, excerpt, content_json, content_html,
  cover_url, cover_storage_bucket, cover_storage_path, external_url, featured_on_home, home_order,
  portfolio_order, seo_title, seo_description, published_at, created_by, updated_by, version,
  created_at, updated_at
)
select
  id, legacy_id, legacy_slug, slug, title, status, categories, excerpt, content_json, content_html,
  cover_url, cover_storage_bucket, cover_storage_path, external_url, featured_on_home, home_order,
  portfolio_order, seo_title, seo_description, published_at, created_by, updated_by, version,
  created_at, updated_at
from _portfolio_migration_cases
where not exists (select 1 from public.portfolio_cases pc where pc.id = _portfolio_migration_cases.id);

insert into public.portfolio_case_media (
  id, case_id, source_url, storage_bucket, storage_path, media_type, alt_text, caption, width, height, sort_order
)
select
  id, case_id, source_url, storage_bucket, storage_path, media_type, alt_text, caption, width, height, sort_order
from _portfolio_migration_media
where not exists (select 1 from public.portfolio_case_media pm where pm.id = _portfolio_migration_media.id);

do $$
begin
  if (select count(*) from public.portfolio_cases) <> 36 then
    raise exception 'portfolio_cases count after apply is not 36.';
  end if;
  if (select count(*) from public.portfolio_case_media) <> (select count(*) from _portfolio_migration_media) then
    raise exception 'portfolio_case_media count after apply does not match dry-run.';
  end if;
  if exists (
    select 1
    from public.portfolio_case_media pm
    left join public.portfolio_cases pc on pc.id = pm.case_id
    where pc.id is null
  ) then
    raise exception 'portfolio_case_media contains invalid case_id.';
  end if;
  if exists (select 1 from public.portfolio_cases where slug like 'novo-case-%') then
    raise exception 'novo-case record was migrated unexpectedly.';
  end if;
  if (select count(*) from public.cases) <> 40 then
    raise exception 'public.cases count changed during apply.';
  end if;
end $$;

commit;
